"""API endpoints for AI-powered notebook evaluation."""

import json
import logging
from fastapi import APIRouter, HTTPException
from fastapi.responses import StreamingResponse

from evaluation.scoring_models import EvaluationContext
from models.session import SessionStatus
from models.evaluation import RubricTemplate
from storage.session_store import session_store
from llm.client import LLMClient
from evaluation.evaluator import EvaluationGenerator

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/evaluate", tags=["evaluate"])


def _ensure_eval_state(notebook) -> None:
    """Ensure eval_state exists on a notebook (backward compat)."""
    from models.session import NotebookEvaluationState
    if notebook.eval_state is None:
        notebook.eval_state = NotebookEvaluationState()

# Module-level singletons
llm_client = LLMClient()
evaluation_generator = EvaluationGenerator(llm_client)


@router.post("/{session_id}")
async def evaluate_notebook(session_id: str):
    """Evaluate a notebook against its rubric (non-streaming).

    Consumes the 7-domain EvaluationContext stored by the understanding phase.
    Performs per-criterion scoring and aggregate calculation.
    Returns the complete EvaluationResult as JSON.
    """
    session = session_store.get_session(session_id)
    if session is None:
        raise HTTPException(
            status_code=404,
            detail={
                "error": "session_not_found",
                "message": "Session not found or has expired. Please upload a notebook first.",
            },
        )

    if not session.rubric_config:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_rubric",
                "message": "No rubric configured for this session. Please save a rubric first.",
            },
        )

    if not session.notebooks or session.notebooks[-1].parsed is None:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_notebook",
                "message": "No parsed notebook found. Please upload a notebook first.",
            },
        )

    notebook = session.notebooks[-1]
    _ensure_eval_state(notebook)
    rubric = session.rubric_config

    # Read the 7-domain EvaluationContext from eval_state (must have run understand first)
    if notebook.eval_state.understanding is None:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_understanding",
                "message": "No understanding context found. Please run the understanding analysis first.",
            },
        )
    try:
        evaluation_context = EvaluationContext.model_validate(notebook.eval_state.understanding)
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail={
                "error": "invalid_context",
                "message": "Stored understanding context is invalid. Please re-run the understanding analysis.",
                "details": [str(e)],
            },
        )

    # Update session status
    session.status = SessionStatus.EVALUATING
    session_store.update_session(session)

    try:
        # Run evaluation with pre-built context (no separate understanding call)
        result = await evaluation_generator.evaluate(
            parsed_notebook=notebook.parsed,
            rubric=rubric,
            evaluation_context=evaluation_context,
        )

        # Store result in per-notebook eval_state
        notebook.eval_state.evaluation_result = result
        session.status = SessionStatus.COMPLETED
        session_store.update_session(session)

        return {
            "session_id": session.session_id,
            "status": "completed",
            "evaluation": result.model_dump(mode="json"),
        }
    except Exception as e:
        session.status = SessionStatus.FAILED
        session_store.update_session(session)
        logger.error(f"Evaluation failed for session {session_id}: {e}")
        raise HTTPException(
            status_code=500,
            detail={
                "error": "evaluation_failed",
                "message": "Failed to evaluate the notebook. Please check your API configuration and try again.",
                "details": [str(e)],
            },
        )


@router.get("/{session_id}/stream")
async def stream_evaluation(session_id: str):
    """Stream evaluation progress as Server-Sent Events.

    Consumes the 7-domain EvaluationContext from the understanding phase.
    Returns an SSE stream with per-criterion scores and final result.
    """
    session = session_store.get_session(session_id)
    if session is None:
        raise HTTPException(
            status_code=404,
            detail={
                "error": "session_not_found",
                "message": "Session not found or has expired.",
            },
        )

    if not session.rubric_config:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_rubric",
                "message": "No rubric configured. Please save a rubric first.",
            },
        )

    if not session.notebooks or session.notebooks[-1].parsed is None:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_notebook",
                "message": "No parsed notebook found. Please upload a notebook first.",
            },
        )

    notebook = session.notebooks[-1]
    _ensure_eval_state(notebook)
    rubric = session.rubric_config

    # Read EvaluationContext from eval_state
    if notebook.eval_state.understanding is None:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "no_understanding",
                "message": "No understanding context found. Please run the understanding analysis first.",
            },
        )
    try:
        evaluation_context = EvaluationContext.model_validate(notebook.eval_state.understanding)
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail={
                "error": "invalid_context",
                "message": "Stored understanding context is invalid. Please re-run the understanding analysis.",
                "details": [str(e)],
            },
        )

    # Update session status
    session.status = SessionStatus.EVALUATING
    session_store.update_session(session)

    async def event_stream():
        yield f"data: {json.dumps({'type': 'start'})}\n\n"
        try:
            async for event in evaluation_generator.evaluate_streaming(
                parsed_notebook=notebook.parsed,
                rubric=rubric,
                evaluation_context=evaluation_context,
            ):
                yield f"data: {json.dumps(event)}\n\n"

                # Store final result when received
                if event["type"] == "result":
                    from models.evaluation import EvaluationResult
                    result = EvaluationResult.model_validate(event["data"])
                    notebook.eval_state.evaluation_result = result
                    session.status = SessionStatus.COMPLETED
                    session_store.update_session(session)

            yield f"data: {json.dumps({'type': 'done'})}\n\n"
        except Exception as e:
            logger.error(f"Streaming evaluation failed for session {session_id}: {e}")
            session.status = SessionStatus.FAILED
            session_store.update_session(session)
            yield f"data: {json.dumps({'type': 'error', 'data': {'message': str(e)}})}\n\n"

    return StreamingResponse(event_stream(), media_type="text/event-stream")

"""API endpoint for notebook file upload."""

import logging
import os
from typing import Optional

from fastapi import APIRouter, File, Header, HTTPException, UploadFile

from core.parser import parse_notebook, validate_notebook
from models.session import SessionStatus
from storage.session_store import session_store
from storage.upload_handler import UploadHandler

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/upload", tags=["upload"])
upload_handler = UploadHandler()


@router.post("")
async def upload_notebook(
    file: UploadFile = File(...),
    session_id: Optional[str] = Header(None),
):
    """Upload a Jupyter notebook (.ipynb) file for evaluation.

    Accepts a single .ipynb file, validates it, parses it with nbformat,
    saves it to a session-scoped temp directory, and returns a structured
    summary of the parsed notebook.

    If no session_id header is provided, a new session is created.
    If session_id is provided, the notebook is added to that session.
    """
    # --- Session management ---
    session = None
    if session_id:
        session = session_store.get_session(session_id)
        if session is None:
            # Frontend-generated session ID — adopt it
            session = session_store.create_session(session_id)
    else:
        session = session_store.create_session()

    # --- File extension check ---
    filename = file.filename or "notebook.ipynb"
    if not filename.lower().endswith(".ipynb"):
        raise HTTPException(
            status_code=400,
            detail={
                "error": "invalid_format",
                "message": "Please upload a valid Jupyter notebook file (.ipynb). "
                f"The file '{filename}' does not appear to be a notebook.",
            },
        )

    # --- Read file content (with size check) ---
    try:
        content = await file.read()
    except Exception as e:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "parse_error",
                "message": "Could not read the uploaded file. The file may be corrupted.",
                "details": [str(e)],
            },
        )

    # --- File size check (D-07) ---
    max_bytes = 1024 * 1024  # We'll use settings but also check early
    from config.settings import settings as app_settings

    max_bytes = app_settings.max_file_size_mb * 1024 * 1024
    if len(content) > max_bytes:
        max_mb = app_settings.max_file_size_mb
        actual_mb = len(content) / (1024 * 1024)
        raise HTTPException(
            status_code=413,
            detail={
                "error": "file_too_large",
                "message": f"File size ({actual_mb:.1f} MB) exceeds the maximum allowed size of {max_mb} MB. "
                f"Please upload a smaller notebook.",
                "details": [
                    f"Uploaded: {actual_mb:.1f} MB",
                    f"Maximum: {max_mb} MB",
                ],
            },
        )

    # --- Validate notebook structure (T-01-01) ---
    is_valid, validation_errors = validate_notebook(content)
    if not is_valid:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "corrupted_notebook",
                "message": "This file doesn't appear to be a valid Jupyter notebook.",
                "details": validation_errors,
            },
        )

    # --- Parse notebook ---
    try:
        parsed = parse_notebook(filename, content)
    except Exception as e:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "parse_error",
                "message": "Could not parse the notebook. The file may be in an unexpected format.",
                "details": [str(e)],
            },
        )

    if not parsed.valid:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "corrupted_notebook",
                "message": "The notebook could not be parsed correctly.",
                "details": parsed.errors,
            },
        )

    # --- Save to temp directory ---
    try:
        file_path = upload_handler.save_upload(session.session_id, filename, content)
    except ValueError as e:
        raise HTTPException(status_code=413, detail={"error": "file_too_large", "message": str(e)})
    except OSError as e:
        logger.error(f"Failed to save upload for session {session.session_id}: {e}")
        raise HTTPException(
            status_code=500,
            detail={
                "error": "storage_error",
                "message": "Failed to save the uploaded file. Please try again.",
            },
        )

    # --- Update session ---
    from models.session import UploadedNotebook

    uploaded = UploadedNotebook(
        filename=filename,
        temp_path=file_path,
        size_bytes=len(content),
        parsed=parsed,
    )
    session.notebooks.append(uploaded)
    session.status = SessionStatus.UPLOADED
    session_store.update_session(session)

    # --- Return success response ---
    return {
        "session_id": session.session_id,
        "status": "uploaded",
        "notebook": parsed.model_dump(),
    }


_BATCH_MAX_FILES = 50


@router.post("/batch")
async def upload_notebook_batch(
    files: list[UploadFile] = File(...),
    session_id: Optional[str] = Header(None),
):
    """Upload multiple Jupyter notebook (.ipynb) files in a single request.

    Validates each file independently (extension, size, nbformat structure).
    Per-file errors do NOT halt the batch — returns per-file success/error
    status so faculty can see which files were accepted and which failed.

    Max 50 files per request (T-04-01 DoS mitigation).
    """
    # --- Enforce max file count ---
    if len(files) > _BATCH_MAX_FILES:
        raise HTTPException(
            status_code=422,
            detail={
                "error": "too_many_files",
                "message": f"Maximum of {_BATCH_MAX_FILES} files per upload request.",
            },
        )

    # --- Session management ---
    session = None
    if session_id:
        session = session_store.get_session(session_id)
        if session is None:
            session = session_store.create_session(session_id)
    else:
        session = session_store.create_session()

    from config.settings import settings as app_settings
    from models.session import NotebookEvaluationState, NotebookStatus, UploadedNotebook

    max_bytes = app_settings.max_file_size_mb * 1024 * 1024
    notebook_results: list[dict] = []
    succeeded = 0
    failed = 0

    for file in files:
        filename = file.filename or "notebook.ipynb"
        file_error = None
        parsed = None
        file_path = None

        # --- Extension check ---
        if not filename.lower().endswith(".ipynb"):
            file_error = f"Invalid file type. Only .ipynb files are accepted."
        else:
            # --- Read file content ---
            try:
                content = await file.read()
            except Exception as e:
                file_error = "Could not read the uploaded file."

            # --- Size check ---
            if file_error is None and len(content) > max_bytes:
                actual_mb = len(content) / (1024 * 1024)
                file_error = (
                    f"File size ({actual_mb:.1f} MB) exceeds the maximum "
                    f"allowed size of {app_settings.max_file_size_mb} MB."
                )

            # --- Validate notebook structure ---
            if file_error is None:
                is_valid, validation_errors = validate_notebook(content)
                if not is_valid:
                    file_error = "Invalid notebook structure."

            # --- Parse notebook ---
            if file_error is None:
                try:
                    parsed = parse_notebook(filename, content)
                except Exception:
                    file_error = "Could not parse the notebook."
                else:
                    if not parsed.valid:
                        file_error = "The notebook could not be parsed correctly."

            # --- Save to temp directory ---
            if file_error is None:
                try:
                    file_path = upload_handler.save_upload(session.session_id, filename, content)
                except (ValueError, OSError) as e:
                    file_error = "Failed to save the uploaded file."

        # --- Build result entry ---
        if file_error is None:
            uploaded = UploadedNotebook(
                filename=filename,
                temp_path=file_path,
                size_bytes=len(content),
                parsed=parsed,
                eval_state=NotebookEvaluationState(status=NotebookStatus.QUEUED),
            )
            session.notebooks.append(uploaded)

            notebook_results.append({
                "filename": filename,
                "status": "uploaded",
                "cells": parsed.total_cells if parsed else 0,
            })
            succeeded += 1
        else:
            notebook_results.append({
                "filename": filename,
                "status": "failed",
                "error": file_error,
            })
            failed += 1

    # --- Update session ---
    if succeeded > 0:
        session.status = SessionStatus.UPLOADED
    else:
        session.status = SessionStatus.FAILED
    session_store.update_session(session)

    return {
        "session_id": session.session_id,
        "total": len(files),
        "succeeded": succeeded,
        "failed": failed,
        "notebooks": notebook_results,
    }

import { useCallback, useState, useEffect } from 'react'
import { CheckCircle2, X } from 'lucide-react'
import Layout from './components/Layout'
import { Button } from '@/components/ui/button'
import StepWizard from './components/StepWizard'
import type { Step } from './components/StepWizard'
import UploadZone from './components/UploadZone'
import ProgressIndicator from './components/ProgressIndicator'
import NotebookPreview from './components/NotebookPreview'
import AISummary from './components/AISummary'
import ErrorDisplay from './components/ErrorDisplay'
import RubricSelector from './components/RubricSelector'
import EvaluationProgress from './components/EvaluationProgress'
import EvaluationResults from './components/EvaluationResults'
import ScoreOverride from './components/ScoreOverride'
import ReportPreview from './components/ReportPreview'
import VivaPreview from './components/VivaPreview'
import { useSessionStore } from './stores/sessionStore'
import { useUpload } from './hooks/useUpload'
import { useUnderstanding } from './hooks/useUnderstanding'
import { useEvaluation } from './hooks/useEvaluation'
import { useBatch } from './hooks/useBatch'
import { useBatchStore } from './stores/batchStore'
import BatchDashboard from './pages/BatchDashboard'
import type { RubricTemplate } from './types/api'

export default function App() {
  const {
    currentStep,
    setCurrentStep,
    parsedNotebook,
    understandingResult,
    sessionId,
    selectedRubric,
    evaluationResult,
    isEvaluating,
    evaluationProgress,
    overrides,
    studentName,
    assignmentName,
    courseName,
    error: storeError,
    setError: setStoreError,
    setSelectedRubric,
    setOverrides,
    addOverride,
    setStudentName,
    setAssignmentName,
    setCourseName,
    setUploadedFile,
    setUnderstandingResult,
    setEvaluationResult,
    setReportStatus,
    setReportRequest,
    setAnalysisResult,
  } = useSessionStore()

  const { uploadFile, isUploading, uploadStage, error: uploadError } = useUpload()
  const { analyze, isAnalyzing, streamingText, error: analysisError, clearError } = useUnderstanding()
  const { startEvaluation, error: evalError } = useEvaluation()
  const batch = useBatch()
  const [showBatchDashboard, setShowBatchDashboard] = useState(false)

  const error = uploadError || analysisError || evalError || storeError

  const handleFilesSelected = useCallback(
    async (files: File[]) => {
      clearError()
      if (files.length === 1) {
        await uploadFile(files[0])
      } else {
        await batch.uploadBatchFiles(files)
        setShowBatchDashboard(true)
      }
    },
    [uploadFile, clearError, batch]
  )

  // Auto-enter batch dashboard when files are uploaded
  const [batchEntered, setBatchEntered] = useState(false)
  useEffect(() => {
    if (batch.queueFiles.length > 0 && !showBatchDashboard && !batchEntered) {
      setBatchEntered(true)
      setShowBatchDashboard(true)
    }
  }, [batch.queueFiles.length, showBatchDashboard, batchEntered])

  const handleRemoveUpload = useCallback(() => {
    setUploadedFile(null, null)
    setUnderstandingResult(null)
    setSelectedRubric(null)
    setEvaluationResult(null)
    setOverrides([])
    setReportStatus(null)
    setReportRequest(null)
    setAnalysisResult(null)
    setCurrentStep(0)
  }, [setUploadedFile, setUnderstandingResult, setSelectedRubric, setEvaluationResult, setOverrides, setReportStatus, setReportRequest, setAnalysisResult, setCurrentStep])

  const handleBackToUpload = useCallback(() => {
    setShowBatchDashboard(false)
    useBatchStore.getState().resetUploadFlow()
  }, [])

  const handleAnalyze = useCallback(async () => {
    clearError()
    await analyze()
  }, [analyze, clearError])

  const handleNext = useCallback(() => {
    if (currentStep < 6) {
      setCurrentStep(currentStep + 1)
    }
  }, [currentStep, setCurrentStep])

  const handleBack = useCallback(() => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1)
    }
  }, [currentStep, setCurrentStep])

  const canGoNext = useCallback((): boolean => {
    switch (currentStep) {
      case 0: // Upload — need ready upload
        return uploadStage === 'ready' && parsedNotebook !== null
      case 1: // Preview — need analysis to complete
        return understandingResult !== null
      case 2: // Summary — always can proceed (reviewed understanding)
        return true
      case 3: // Rubric — need rubric selected/saved
        return selectedRubric !== null
      case 4: // Evaluate — need evaluation complete
        return evaluationResult !== null
      case 5: // Override — always can proceed (overrides optional)
        return true
      case 6: // Report — last step, Finish button
        return false
      default:
        return false
    }
  }, [currentStep, uploadStage, parsedNotebook, understandingResult, selectedRubric, evaluationResult])

  const canGoBack = currentStep > 0

  const handleDismissError = useCallback(() => {
    setStoreError(null)
    clearError()
  }, [setStoreError, clearError])

  // ---- Rubric handlers ----
  const handleRubricReady = useCallback((rubric: RubricTemplate) => {
    setSelectedRubric(rubric)
  }, [setSelectedRubric])

  // ---- Evaluation handlers ----
  const handleStartEvaluation = useCallback(() => {
    if (sessionId) {
      startEvaluation(sessionId)
    }
  }, [sessionId, startEvaluation])

  // ---- Override handlers ----
  const handleScoreOverride = useCallback((criterionName: string, newScore: number) => {
    const original = evaluationResult?.criteria_scores.find(
      s => s.criterion_name === criterionName
    )
    if (original) {
      addOverride({
        criterion_name: criterionName,
        original_score: original.score,
        overridden_score: newScore,
        reason: '',
      })
    }
  }, [evaluationResult, addOverride])

  const handleOverrideConfirm = useCallback(
    (criterionName: string, newScore: number, reason: string) => {
      const original = evaluationResult?.criteria_scores.find(
        s => s.criterion_name === criterionName
      )
      if (original) {
        addOverride({
          criterion_name: criterionName,
          original_score: original.score,
          overridden_score: newScore,
          reason,
        })
      }
    },
    [evaluationResult, addOverride]
  )

  const handleResetOverride = useCallback((criterionName: string) => {
    setOverrides(overrides.filter(o => o.criterion_name !== criterionName))
  }, [overrides, setOverrides])

  // ---- Report handlers ----
  const handleStudentNameChange = useCallback((name: string) => {
    setStudentName(name)
  }, [setStudentName])

  const handleAssignmentNameChange = useCallback((name: string) => {
    setAssignmentName(name)
  }, [setAssignmentName])

  const handleCourseNameChange = useCallback((name: string) => {
    setCourseName(name)
  }, [setCourseName])

  // Determine upload stage display
  const displayUploadStage = isUploading
    ? uploadStage
    : parsedNotebook
      ? 'ready'
      : 'idle'

  const steps: Step[] = [
    // Step 0: Upload (Phase 1)
    {
      id: 'upload',
      title: 'Upload',
      description: 'Upload a .ipynb file',
      component: (
        <div className="space-y-6">
          {!parsedNotebook && !showBatchDashboard ? (
            <>
              <UploadZone
                onFilesSelected={handleFilesSelected}
                onRemove={handleRemoveUpload}
                maxSizeMB={20}
                disabled={isUploading}
                multiple={true}
              />

              <ProgressIndicator currentStage={displayUploadStage} />
            </>
          ) : parsedNotebook ? (
            <div className="rounded-lg border border-green-500/30 bg-green-50/50 dark:bg-green-950/20 p-6 text-center">
              <CheckCircle2 size={28} className="mx-auto text-green-500 mb-2" />
              <p className="text-sm text-green-700 dark:text-green-300 font-medium mb-1">
                {parsedNotebook.filename} uploaded
              </p>
              <p className="text-xs text-green-600 dark:text-green-400">
                {parsedNotebook.total_cells} cells
                {sessionId && (
                  <span className="block mt-1 font-mono opacity-70">
                    Session: {sessionId.slice(0, 8)}...
                  </span>
                )}
              </p>
              <Button
                variant="outline"
                size="sm"
                onClick={handleRemoveUpload}
                className="mt-3"
              >
                <X size={14} className="mr-1" /> Remove & re-upload
              </Button>
            </div>
          ) : null}

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ),
    },
    // Step 1: Preview (Phase 1)
    {
      id: 'preview',
      title: 'Preview',
      description: 'Review notebook content',
      component: (
        <div className="space-y-4">
          {parsedNotebook ? (
            <NotebookPreview
              cells={parsedNotebook.cells || []}
              onAnalyze={handleAnalyze}
              isAnalyzing={isAnalyzing}
            />
          ) : (
            <div className="text-center py-12 text-muted-foreground">
              No notebook data available. Please upload a notebook first.
            </div>
          )}

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ),
    },
    // Step 2: AI Summary (Phase 1)
    {
      id: 'summary',
      title: 'AI Summary',
      description: 'View AI understanding',
      component: (
        <div className="space-y-4">
          <AISummary
            understanding={understandingResult}
            isAnalyzing={isAnalyzing}
            streamingText={streamingText}
          />

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ),
    },
    // Step 3: Rubric Configuration (NEW)
    {
      id: 'rubric',
      title: 'Rubric',
      description: 'Configure evaluation rubric',
      component: (
        <div className="space-y-6">
          <RubricSelector
            onRubricReady={handleRubricReady}
            initialRubric={selectedRubric}
          />

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ),
    },
    // Step 4: Evaluation (NEW)
    {
      id: 'evaluate',
      title: 'Evaluate',
      description: 'AI evaluation results',
      component: (
        <div className="space-y-6">
          <EvaluationProgress
            progress={evaluationProgress}
            isEvaluating={isEvaluating}
            onStartEvaluation={handleStartEvaluation}
            evaluated={evaluationResult !== null}
          />

          {evaluationResult && (
            <EvaluationResults
              result={evaluationResult}
              isLoading={isEvaluating}
              isEvaluating={isEvaluating}
              onOverride={handleScoreOverride}
            />
          )}

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ),
    },
    // Step 5: Review & Override (NEW)
    {
      id: 'override',
      title: 'Review',
      description: 'Override scores if needed',
      component: evaluationResult ? (
        <div className="space-y-6">
          <ScoreOverride
            evaluationResult={evaluationResult}
            overrides={overrides}
            onOverride={handleOverrideConfirm}
            onResetOverride={handleResetOverride}
          />

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />
        </div>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          Please complete the evaluation first before reviewing scores.
        </div>
      ),
    },
    // Step 6: Report (NEW)
    {
      id: 'report',
      title: 'Report',
      description: 'Preview & download PDF',
      component: evaluationResult ? (
        <div className="space-y-6">
          <ReportPreview
            sessionId={sessionId}
            evaluationResult={evaluationResult}
            overrides={overrides}
            studentName={studentName}
            assignmentName={assignmentName}
            courseName={courseName}
            onStudentNameChange={handleStudentNameChange}
            onAssignmentNameChange={handleAssignmentNameChange}
            onCourseNameChange={handleCourseNameChange}
          />

          <ErrorDisplay
            error={error}
            variant="inline"
            onDismiss={handleDismissError}
          />

          {evaluationResult && <VivaPreview />}
        </div>
      ) : (
        <div className="text-center py-12 text-muted-foreground">
          No evaluation results available. Please complete the evaluation first.
        </div>
      ),
    },
  ]

  return (
    <Layout>
      {showBatchDashboard ? (
        <BatchDashboard onBackToUpload={handleBackToUpload} />
      ) : (
        <>
          {/* Toast notification for errors */}
          <ErrorDisplay
            error={error}
            variant="toast"
            onDismiss={handleDismissError}
          />

          <StepWizard
            steps={steps}
            currentStep={currentStep}
            onNext={handleNext}
            onBack={handleBack}
            canGoNext={canGoNext()}
            canGoBack={canGoBack}
          />
        </>
      )}
    </Layout>
  )
}

import { useState, useMemo, useCallback } from 'react'
import {
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
  Check,
  X,
  RefreshCw,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import type { ComparisonResponse } from '@/types/api'

type SortKey = 'student_name' | 'aggregate_percentage' | string  // criterion names
type SortDir = 'asc' | 'desc'

interface BatchComparisonTableProps {
  data: ComparisonResponse | null
  loading: boolean
  selectedStudent: string | null
  onSelectStudent: (filename: string | null) => void
  onScoreEdit: (filename: string, criterionName: string, newScore: number) => void
  isReevaluating: Record<string, boolean>
}

function formatScore(score: number): string {
  return score.toFixed(1)
}

function statusBadgeColor(status: string): string {
  switch (status) {
    case 'completed': return 'bg-green-100 text-green-700 dark:bg-green-950 dark:text-green-300'
    case 'failed': return 'bg-destructive/10 text-destructive'
    case 'evaluating':
    case 'understanding':
    case 'analyzing': return 'bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-300'
    default: return 'bg-muted text-muted-foreground'
  }
}

export default function BatchComparisonTable({
  data,
  loading,
  selectedStudent,
  onSelectStudent,
  onScoreEdit,
  isReevaluating,
}: BatchComparisonTableProps) {
  const [sortKey, setSortKey] = useState<SortKey>('student_name')
  const [sortDir, setSortDir] = useState<SortDir>('asc')
  const [editingCell, setEditingCell] = useState<{
    filename: string
    criterion: string
  } | null>(null)
  const [editValue, setEditValue] = useState<number>(0)

  // Extract all criterion names from the first row with scores
  const criteria = useMemo(() => {
    if (!data || data.rows.length === 0) return []
    const names = new Set<string>()
    for (const row of data.rows) {
      for (const cs of row.per_criterion_scores) {
        names.add(cs.criterion_name)
      }
    }
    return Array.from(names)
  }, [data])

  // Sort the rows
  const sortedRows = useMemo(() => {
    if (!data) return []
    const rows = [...data.rows]
    rows.sort((a, b) => {
      let aVal: string | number = ''
      let bVal: string | number = ''

      if (sortKey === 'student_name') {
        aVal = a.student_name.toLowerCase()
        bVal = b.student_name.toLowerCase()
      } else if (sortKey === 'aggregate_percentage') {
        aVal = a.aggregate_percentage
        bVal = b.aggregate_percentage
      } else {
        // Criterion score
        const aScore = a.per_criterion_scores.find((s) => s.criterion_name === sortKey)
        const bScore = b.per_criterion_scores.find((s) => s.criterion_name === sortKey)
        aVal = aScore?.score ?? 0
        bVal = bScore?.score ?? 0
      }

      if (typeof aVal === 'string') {
        return sortDir === 'asc' ? aVal.localeCompare(bVal as string) : (bVal as string).localeCompare(aVal)
      }
      return sortDir === 'asc' ? (aVal as number) - (bVal as number) : (bVal as number) - (aVal as number)
    })
    return rows
  }, [data, sortKey, sortDir])

  const toggleSort = useCallback((key: SortKey) => {
    setSortDir((prev) => (sortKey === key && prev === 'asc' ? 'desc' : 'asc'))
    setSortKey(key)
  }, [sortKey])

  const handleCellClick = useCallback((filename: string, criterion: string, currentScore: number) => {
    setEditingCell({ filename, criterion })
    setEditValue(currentScore)
  }, [])

  const handleCellSave = useCallback((filename: string, criterion: string) => {
    if (editValue >= 0 && editValue <= 5) {
      onScoreEdit(filename, criterion, editValue)
    }
    setEditingCell(null)
  }, [editValue, onScoreEdit])

  const handleCellCancel = useCallback(() => {
    setEditingCell(null)
  }, [])

  const handleRowClick = useCallback((filename: string) => {
    if (!editingCell || editingCell.filename !== filename) {
      onSelectStudent(selectedStudent === filename ? null : filename)
    }
  }, [selectedStudent, onSelectStudent, editingCell])

  const SortIcon = ({ columnKey }: { columnKey: SortKey }) => {
    if (sortKey !== columnKey) return <ArrowUpDown size={12} className="ml-1 opacity-40" />
    return sortDir === 'asc' ? <ArrowUp size={12} className="ml-1" /> : <ArrowDown size={12} className="ml-1" />
  }

  if (loading && !data) {
    return (
      <Card>
        <CardHeader><CardTitle className="text-base">Comparison Table</CardTitle></CardHeader>
        <CardContent>
          <div className="space-y-3">
            <Skeleton className="h-8 w-full" />
            <Skeleton className="h-8 w-full" />
            <Skeleton className="h-8 w-full" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || data.rows.length === 0) {
    return (
      <Card>
        <CardHeader><CardTitle className="text-base">Comparison Table</CardTitle></CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground text-center py-8">
            No evaluation data available. Complete evaluations to see the comparison table.
          </p>
        </CardContent>
      </Card>
    )
  }

  const isSelected = (filename: string) => selectedStudent === filename

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center justify-between">
          <span>Comparison Table</span>
          <span className="text-xs font-normal text-muted-foreground">
            {data.total} student{data.total !== 1 ? 's' : ''}
          </span>
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0 overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b">
              <th
                className="sticky left-0 bg-card z-10 px-3 py-2.5 text-left font-medium text-muted-foreground text-xs cursor-pointer hover:text-foreground whitespace-nowrap"
                onClick={() => toggleSort('student_name')}
              >
                Student <SortIcon columnKey="student_name" />
              </th>
              {criteria.map((c) => (
                <th
                  key={c}
                  className="px-2 py-2.5 text-center font-medium text-muted-foreground text-xs cursor-pointer hover:text-foreground whitespace-nowrap"
                  onClick={() => toggleSort(c)}
                >
                  {c} <SortIcon columnKey={c} />
                </th>
              ))}
              <th
                className="px-3 py-2.5 text-right font-medium text-muted-foreground text-xs cursor-pointer hover:text-foreground whitespace-nowrap"
                onClick={() => toggleSort('aggregate_percentage')}
              >
                Total <SortIcon columnKey="aggregate_percentage" />
              </th>
              <th className="px-2 py-2.5 text-center font-medium text-muted-foreground text-xs whitespace-nowrap">
                Status
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedRows.map((row) => (
              <tr
                key={row.filename}
                className={cn(
                  'border-b last:border-0 transition-colors cursor-pointer hover:bg-muted/50',
                  isSelected(row.filename) && 'bg-primary/5 hover:bg-primary/10'
                )}
                onClick={() => handleRowClick(row.filename)}
              >
                <td className="sticky left-0 bg-card z-10 px-3 py-3 font-medium text-sm">
                  <div className="flex items-center gap-2">
                    <span>{row.student_name}</span>
                    <span className="text-xs text-muted-foreground font-mono">
                      {row.filename}
                    </span>
                  </div>
                </td>
                {criteria.map((c) => {
                  const cs = row.per_criterion_scores.find((s) => s.criterion_name === c)
                  const score = cs?.score ?? 0
                  const isEditing = editingCell?.filename === row.filename && editingCell?.criterion === c

                  return (
                    <td
                      key={c}
                      className={cn(
                        'px-2 py-3 text-center',
                        isEditing && 'bg-primary/5'
                      )}
                      onClick={(e) => {
                        if (!isEditing) {
                          e.stopPropagation()
                          handleCellClick(row.filename, c, score)
                        }
                      }}
                    >
                      {isEditing ? (
                        <div className="flex items-center justify-center gap-0.5">
                          <input
                            type="number"
                            min={0}
                            max={5}
                            step={0.5}
                            value={editValue}
                            onChange={(e) => setEditValue(parseFloat(e.target.value) || 0)}
                            className="w-12 h-7 text-center text-xs border rounded px-1"
                            autoFocus
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') handleCellSave(row.filename, c)
                              if (e.key === 'Escape') handleCellCancel()
                            }}
                            onClick={(e) => e.stopPropagation()}
                          />
                          <button
                            onClick={(e) => { e.stopPropagation(); handleCellSave(row.filename, c) }}
                            className="p-0.5 text-green-500 hover:text-green-600"
                          >
                            <Check size={12} />
                          </button>
                          <button
                            onClick={(e) => { e.stopPropagation(); handleCellCancel() }}
                            className="p-0.5 text-destructive hover:text-destructive/80"
                          >
                            <X size={12} />
                          </button>
                        </div>
                      ) : (
                        <span className="tabular-nums">{formatScore(score)}</span>
                      )}
                    </td>
                  )
                })}
                <td className="px-3 py-3 text-right tabular-nums font-medium">
                  {formatScore(row.aggregate_percentage)}%
                </td>
                <td className="px-2 py-3 text-center">
                  <div className="flex items-center justify-center gap-1">
                    <span
                      className={cn(
                        'inline-block text-xs px-1.5 py-0.5 rounded-full',
                        statusBadgeColor(row.status)
                      )}
                    >
                      {row.status}
                    </span>
                    {isReevaluating[row.filename] && (
                      <RefreshCw size={12} className="animate-spin text-muted-foreground" />
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </CardContent>
    </Card>
  )
}

import { FileText, CheckCircle2, AlertCircle, Loader2, Trash2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import type { QueueFileEntry } from '@/types/api'

interface BatchFileListProps {
  files: QueueFileEntry[]
  onRemove: (id: string) => void
  disabled?: boolean
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return bytes + ' B'
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB'
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB'
}

const statusConfig: Record<QueueFileEntry['status'], {
  label: string
  icon: typeof FileText
  color: string
  bgColor: string
}> = {
  pending: {
    label: 'Pending',
    icon: FileText,
    color: 'text-muted-foreground',
    bgColor: 'bg-muted/50',
  },
  uploading: {
    label: 'Uploading...',
    icon: Loader2,
    color: 'text-blue-500',
    bgColor: 'bg-blue-50/50 dark:bg-blue-950/20',
  },
  validated: {
    label: 'Validated',
    icon: CheckCircle2,
    color: 'text-green-500',
    bgColor: 'bg-green-50/50 dark:bg-green-950/20',
  },
  failed: {
    label: 'Failed',
    icon: AlertCircle,
    color: 'text-destructive',
    bgColor: 'bg-destructive/10',
  },
}

export default function BatchFileList({ files, onRemove, disabled = false }: BatchFileListProps) {
  if (files.length === 0) return null

  return (
    <div className="space-y-2">
      <p className="text-sm font-medium text-muted-foreground">
        {files.length} file{files.length !== 1 ? 's' : ''} selected
      </p>
      <div className="divide-y rounded-lg border">
        {files.map((entry) => {
          const cfg = statusConfig[entry.status]
          const Icon = cfg.icon
          return (
            <div
              key={entry.id}
              className={cn(
                'flex items-center gap-3 px-4 py-3 transition-colors',
                cfg.bgColor
              )}
            >
              <Icon
                size={18}
                className={cn(
                  cfg.color,
                  entry.status === 'uploading' && 'animate-spin'
                )}
              />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">
                  {entry.file.name}
                </p>
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <span>{formatSize(entry.file.size)}</span>
                  {entry.cells !== undefined && (
                    <>
                      <span>&middot;</span>
                      <span>{entry.cells} cells</span>
                    </>
                  )}
                  <span>&middot;</span>
                  <span className={cfg.color}>{cfg.label}</span>
                </div>
                {entry.error && (
                  <p className="text-xs text-destructive mt-1">{entry.error}</p>
                )}
              </div>
              {entry.status !== 'uploading' && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 shrink-0"
                  onClick={() => onRemove(entry.id)}
                  disabled={disabled}
                  aria-label={`Remove ${entry.file.name}`}
                >
                  <Trash2 size={14} />
                </Button>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { cn } from '@/lib/utils'
import { Progress } from '@/components/ui/progress'
import { AlertCircle } from 'lucide-react'
import type { BatchStatusResponse, BatchStatusNotebookEntry } from '@/types/api'

interface BatchProgressBarProps {
  status: BatchStatusResponse | null
  className?: string
}

function getPct(total: number, completed: number): number {
  if (total === 0) return 0
  return Math.round((completed / total) * 100)
}

function getStatusColor(status: string): string {
  switch (status) {
    case 'queued': return 'bg-gray-400'
    case 'understanding': return 'bg-blue-500'
    case 'evaluating': return 'bg-amber-500'
    case 'analyzing': return 'bg-purple-500'
    case 'completed': return 'bg-green-500'
    case 'failed': return 'bg-red-500'
    default: return 'bg-gray-400'
  }
}

function getStatusLabel(status: string): string {
  switch (status) {
    case 'queued': return 'Queued'
    case 'understanding': return 'Understanding'
    case 'evaluating': return 'Evaluating'
    case 'analyzing': return 'Analyzing'
    case 'completed': return 'Completed'
    case 'failed': return 'Failed'
    default: return status.charAt(0).toUpperCase() + status.slice(1)
  }
}

export default function BatchProgressBar({ status, className }: BatchProgressBarProps) {
  if (!status) return null

  const pct = getPct(status.total, status.completed + status.failed)
  const doneCount = status.completed
  const failedCount = status.failed
  const total = status.total
  const isTerminal = ['completed', 'failed', 'completed_with_errors'].includes(status.overall_status)

  return (
    <div className={cn('space-y-2', className)}>
      <div className="flex items-center justify-between text-sm">
        <span className="font-medium">
          {isTerminal ? 'Evaluation complete' : 'Evaluating...'}
        </span>
        <span className="text-muted-foreground">
          {doneCount + failedCount}/{total} complete
          {failedCount > 0 && (
            <span className="text-destructive ml-1">
              ({failedCount} failed)
            </span>
          )}
        </span>
      </div>
      <Progress value={pct} className="h-2.5" />
      <div className="flex items-center gap-3 text-xs text-muted-foreground">
        <span className="flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-green-500" />
          {doneCount} completed
        </span>
        {failedCount > 0 && (
          <span className="flex items-center gap-1">
            <span className="w-2 h-2 rounded-full bg-destructive" />
            {failedCount} failed
          </span>
        )}
        {(total - doneCount - failedCount) > 0 && (
          <span className="flex items-center gap-1">
            <span className="w-2 h-2 rounded-full bg-blue-500" />
            {total - doneCount - failedCount} in progress
          </span>
        )}
      </div>

      {/* Per-notebook status grid */}
      {status.notebooks && status.notebooks.length > 0 && (
        <div className="mt-4 space-y-1">
          {status.notebooks.map((nb: BatchStatusNotebookEntry) => (
            <div
              key={nb.filename}
              className="flex items-center gap-2 text-xs py-1 px-2 rounded hover:bg-muted/50"
            >
              <span
                className={cn(
                  'w-2 h-2 rounded-full shrink-0',
                  getStatusColor(nb.status)
                )}
              />
              <span className="text-muted-foreground w-20 shrink-0">
                {getStatusLabel(nb.status)}
              </span>
              <span className="font-mono truncate flex-1">
                {nb.filename}
              </span>
              <span className="tabular-nums text-muted-foreground shrink-0 ml-2">
                {nb.progress_pct}%
              </span>
              {nb.error && (
                <span title={nb.error} className="shrink-0 text-destructive">
                  <AlertCircle size={12} />
                </span>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useCallback, useEffect, useState, useRef } from 'react'
import {
  X,
  Download,
  RefreshCw,
  RotateCcw,
  AlertCircle,
  CheckCircle2,
  Loader2,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { useBatchStore } from '@/stores/batchStore'
import { apiClient } from '@/services/api'
import type { ComparisonRow, EvaluationResult } from '@/types/api'

interface BatchSideDrawerProps {
  row: ComparisonRow | null
  open: boolean
  onClose: () => void
  onReevaluate: (filename: string) => void
  onRecalculate: (filename: string) => void
  isReevaluating: boolean
}

function SectionHeader({ title }: { title: string }) {
  return <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">{title}</h4>
}

interface FullEvaluationData {
  evaluation_result: EvaluationResult | null
  analysis_result?: {
    viva_questions: Array<{ question: string; category: string; expected_answer: string[] }>
    weak_areas: Array<{ topic: string; evidence: string[]; suggestion: string }>
  } | null
  error?: string | null
}

export default function BatchSideDrawer({
  row,
  open,
  onClose,
  onReevaluate,
  onRecalculate,
  isReevaluating,
}: BatchSideDrawerProps) {
  const [evaluationData, setEvaluationData] = useState<FullEvaluationData | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [downloadSuccess, setDownloadSuccess] = useState<string | null>(null)
  const [downloadError, setDownloadError] = useState<string | null>(null)
  const [reevaluateError, setReevaluateError] = useState<string | null>(null)
  const sessionId = useBatchStore((s) => s.batchSessionId)
  const prevFilenameRef = useRef<string | null>(null)

  // Load full evaluation data when the selected student changes
  useEffect(() => {
    if (!row || !sessionId) {
      setEvaluationData(null)
      return
    }

    // Avoid re-fetching if same student
    if (prevFilenameRef.current === row.filename && evaluationData) return
    prevFilenameRef.current = row.filename

    // Per-notebook evaluation details are not available via the current API.
    // The comparison table row already provides aggregate and per-criterion scores.
    setEvaluationData({
      evaluation_result: null,
      error: null,
    })
  }, [row?.filename, sessionId]) // eslint-disable-line react-hooks/exhaustive-deps

  const getSessionId = useCallback(() => {
    return useBatchStore.getState().batchSessionId
  }, [])

  const handleDownloadPdf = useCallback(async () => {
    const sid = getSessionId()
    if (!sid || !row) return

    setDownloadSuccess(null)
    setDownloadError(null)
    try {
      // Generate report first
      await apiClient.generateReport(sid, {
        mode: 'scorecard',
        student_name: row.student_name,
        assignment_name: 'Batch Evaluation',
        course_name: '',
      })
      // Trigger download
      const downloadUrl = apiClient.downloadReportUrl(sid)
      // For batch, we need individual PDF — use the ZIP endpoint
      // Or trigger individual report generation
      window.open(downloadUrl, '_blank')
      setDownloadSuccess('PDF download started')
      setTimeout(() => setDownloadSuccess(null), 3000)
    } catch (err) {
      setDownloadError('Download failed')
      setTimeout(() => setDownloadError(null), 3000)
    }
  }, [row, getSessionId])

  const handleReevaluate = useCallback(async () => {
    if (!row) return
    setReevaluateError(null)
    try {
      await onReevaluate(row.filename)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Re-evaluation failed'
      setReevaluateError(message)
      // Auto-clear after 8 seconds
      setTimeout(() => setReevaluateError(null), 8000)
    }
  }, [onReevaluate, row?.filename])

  if (!open || !row) return null

  return (
    <div className="fixed inset-y-0 right-0 w-[480px] max-w-[90vw] bg-background border-l shadow-xl z-50 flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b">
        <div className="min-w-0 flex-1">
          <h3 className="text-sm font-semibold truncate">{row.student_name}</h3>
          <p className="text-xs text-muted-foreground font-mono truncate">
            {row.filename}
          </p>
        </div>
        <Button variant="ghost" size="icon" onClick={onClose} className="shrink-0 ml-2">
          <X size={16} />
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {/* Status & Score Summary */}
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <span className={cn(
                'text-xs font-medium px-2 py-0.5 rounded-full',
                row.status === 'completed' ? 'bg-green-100 text-green-700 dark:bg-green-950 dark:text-green-300' :
                row.status === 'failed' ? 'bg-destructive/10 text-destructive' :
                'bg-muted text-muted-foreground'
              )}>
                {row.status}
              </span>
              <span className="text-sm font-semibold">
                {row.aggregate_percentage.toFixed(1)}%
              </span>
            </div>
            {row.error && (
              <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 rounded p-2">
                <AlertCircle size={12} className="mt-0.5 shrink-0" />
                <span>{row.error}</span>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Per-Criterion Scores */}
        <div>
          <SectionHeader title="Criterion Scores" />
          <div className="space-y-2">
            {row.per_criterion_scores.map((cs) => (
              <div
                key={cs.criterion_name}
                className="flex items-center justify-between text-sm bg-muted/30 rounded p-2"
              >
                <div className="min-w-0 flex-1">
                  <p className="truncate font-medium">{cs.criterion_name}</p>
                  <p className="text-xs text-muted-foreground">
                    Weight: {cs.weight}% | Contribution: {cs.contribution_pct.toFixed(1)}%
                  </p>
                </div>
                <span className={cn(
                  'ml-3 font-semibold tabular-nums',
                  cs.score >= 4 ? 'text-green-600 dark:text-green-400' :
                  cs.score >= 3 ? 'text-amber-600 dark:text-amber-400' :
                  'text-destructive'
                )}>
                  {cs.score.toFixed(1)}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Loading state */}
        {isLoading && (
          <div className="space-y-3">
            <Skeleton className="h-20 w-full" />
            <Skeleton className="h-20 w-full" />
          </div>
        )}

        {/* Error loading details */}
        {loadError && (
          <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 rounded p-3">
            <AlertCircle size={12} className="mt-0.5 shrink-0" />
            <span>{loadError}</span>
          </div>
        )}

        {/* Re-evaluate error feedback */}
        {reevaluateError && (
          <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 rounded p-3">
            <AlertCircle size={12} className="mt-0.5 shrink-0" />
            <span>{reevaluateError}</span>
          </div>
        )}

        {/* Action Buttons */}
        <div>
          <SectionHeader title="Actions" />
          <div className="grid grid-cols-2 gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleReevaluate}
              disabled={isReevaluating}
              className="gap-1.5"
            >
              {isReevaluating ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <RefreshCw size={14} />
              )}
              Re-evaluate
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={() => onRecalculate(row.filename)}
              disabled={isReevaluating || row.status !== 'completed'}
              className="gap-1.5"
            >
              <RotateCcw size={14} />
              Recalculate
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={handleDownloadPdf}
              disabled={!row.has_report}
              className="gap-1.5"
            >
              <Download size={14} />
              Download PDF
            </Button>
          </div>
        </div>

        {/* Success messages */}
        {downloadSuccess && (
          <div className="flex items-center gap-2 text-xs text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-950/20 rounded p-2">
            <CheckCircle2 size={12} />
            <span>{downloadSuccess}</span>
          </div>
        )}

        {/* Download error messages */}
        {downloadError && (
          <div className="flex items-start gap-2 text-xs text-destructive bg-destructive/10 rounded p-3">
            <AlertCircle size={12} className="mt-0.5 shrink-0" />
            <span>{downloadError}</span>
          </div>
        )}

        {/* AI Summary (if available) */}
        {evaluationData?.evaluation_result?.ai_summary && (
          <div>
            <SectionHeader title="AI Summary" />
            <p className="text-sm text-muted-foreground bg-muted/30 rounded p-3">
              {evaluationData.evaluation_result.ai_summary}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { AlertCircle, X, ChevronDown, ChevronUp } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/ui/card'
import type { ApiError } from '@/types/api'

interface ErrorDisplayProps {
  error: ApiError | null
  variant: 'toast' | 'inline'
  onDismiss?: () => void
}

export default function ErrorDisplay({ error, variant, onDismiss }: ErrorDisplayProps) {
  const [visible, setVisible] = useState(false)
  const [showDetails, setShowDetails] = useState(false)

  useEffect(() => {
    if (error) {
      setVisible(true)
    } else {
      setVisible(false)
      setShowDetails(false)
    }
  }, [error])

  // Auto-dismiss toast after 5 seconds
  useEffect(() => {
    if (variant === 'toast' && visible && error) {
      const timer = setTimeout(() => {
        setVisible(false)
        onDismiss?.()
      }, 5000)
      return () => clearTimeout(timer)
    }
  }, [variant, visible, error, onDismiss])

  if (!error || !visible) return null

  if (variant === 'toast') {
    return (
      <div
        className={cn(
          'fixed bottom-6 right-6 z-50 max-w-sm animate-in slide-in-from-right',
          'rounded-lg border border-red-200 dark:border-red-900/50 bg-white dark:bg-red-950/90 shadow-lg'
        )}
        role="alert"
      >
        <div className="flex items-start gap-3 p-4">
          <AlertCircle size={20} className="text-destructive shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-foreground">
              {error.message || 'An error occurred'}
            </p>
            {error.details && error.details.length > 0 && (
              <p className="text-xs text-muted-foreground mt-1 line-clamp-1">
                {error.details[0]}
              </p>
            )}
          </div>
          {onDismiss && (
            <button
              onClick={() => {
                setVisible(false)
                onDismiss()
              }}
              className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
              aria-label="Dismiss"
            >
              <X size={16} />
            </button>
          )}
        </div>
      </div>
    )
  }

  // Inline variant
  return (
    <Card className="border-red-300 dark:border-red-900/50 bg-red-50/50 dark:bg-red-950/20">
      <CardContent className="p-4">
        <div className="flex items-start gap-3">
          <AlertCircle size={20} className="text-destructive shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <div className="flex items-start justify-between gap-2">
              <div>
                <p className="text-sm font-medium text-red-800 dark:text-red-300">
                  {error.message || 'An error occurred'}
                </p>
                {error.error && (
                  <p className="text-xs text-red-600 dark:text-red-400 mt-0.5 font-mono">
                    Error type: {error.error}
                  </p>
                )}
              </div>
              {onDismiss && (
                <button
                  onClick={() => {
                    setVisible(false)
                    onDismiss()
                  }}
                  className="shrink-0 text-red-500 hover:text-red-700 dark:hover:text-red-300 transition-colors"
                  aria-label="Dismiss"
                >
                  <X size={16} />
                </button>
              )}
            </div>

            {/* Expandable details */}
            {error.details && error.details.length > 0 && (
              <div className="mt-2">
                <button
                  onClick={() => setShowDetails(!showDetails)}
                  className="flex items-center gap-1 text-xs text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-200 transition-colors"
                >
                  {showDetails ? (
                    <ChevronUp size={14} />
                  ) : (
                    <ChevronDown size={14} />
                  )}
                  {showDetails ? 'Hide details' : 'Show details'}
                </button>

                {showDetails && (
                  <ul className="mt-2 space-y-1">
                    {error.details.map((detail, i) => (
                      <li
                        key={i}
                        className="text-xs text-red-700 dark:text-red-400 font-mono bg-red-100/50 dark:bg-red-900/30 px-2 py-1 rounded"
                      >
                        {detail}
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

import { Loader2, Check, Circle, Play } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface EvaluationProgressProps {
  progress: { step: string; status: string } | null
  isEvaluating: boolean
  onStartEvaluation: () => void
  evaluated: boolean
}

const STEPS = [
  { key: 'understanding', label: 'Understanding notebook' },
  { key: 'evaluating', label: 'Evaluating criteria' },
  { key: 'calculating', label: 'Calculating marks' },
]

function getStepIndex(stepText: string): number {
  const lower = stepText.toLowerCase()
  if (lower.includes('understand')) return 0
  if (lower.includes('evaluat')) return 1
  if (lower.includes('calculat')) return 2
  return -1
}

export default function EvaluationProgress({
  progress,
  isEvaluating,
  onStartEvaluation,
  evaluated,
}: EvaluationProgressProps) {
  const currentStepIndex = progress ? getStepIndex(progress.step) : -1

  const getStepIcon = (index: number) => {
    if (progress && index < currentStepIndex) {
      return <Check size={18} className="text-green-500" />
    }
    if (progress && index === currentStepIndex) {
      return <Loader2 size={18} className="text-primary animate-spin" />
    }
    if (evaluated) {
      return <Check size={18} className="text-green-500" />
    }
    return <Circle size={18} className="text-muted-foreground/40" />
  }

  const getStepStyle = (index: number) => {
    if (progress && index < currentStepIndex) return 'text-green-600 dark:text-green-400'
    if (progress && index === currentStepIndex) return 'text-primary font-medium'
    if (evaluated) return 'text-green-600 dark:text-green-400'
    return 'text-muted-foreground/50'
  }

  const getLineStyle = (index: number) => {
    if (progress && index < currentStepIndex - 1) return 'bg-green-500'
    if (progress && index === currentStepIndex - 1) return 'bg-primary/30'
    if (evaluated) return 'bg-green-500'
    return 'bg-muted-foreground/15'
  }

  const getCircleBg = (index: number) => {
    if (progress && index < currentStepIndex) return 'bg-green-100 dark:bg-green-900/30'
    if (progress && index === currentStepIndex) return 'bg-primary/10'
    if (evaluated) return 'bg-green-100 dark:bg-green-900/30'
    return 'bg-muted/30'
  }

  // Not started yet
  if (!isEvaluating && !evaluated) {
    return (
      <div className="space-y-6">
        {/* Step indicator */}
        <div className="w-full max-w-lg mx-auto py-4">
          <div className="flex items-center justify-between">
            {STEPS.map((step, index) => (
              <div key={step.key} className="flex items-center">
                <div className="flex flex-col items-center gap-1.5">
                  <div className={cn(
                    'flex items-center justify-center w-8 h-8 rounded-full transition-all',
                    getCircleBg(index)
                  )}>
                    <Circle size={18} className="text-muted-foreground/40" />
                  </div>
                  <span className={cn('text-xs transition-colors', getStepStyle(index))}>
                    {step.label}
                  </span>
                </div>
                {index < STEPS.length - 1 && (
                  <div className={cn('w-8 md:w-12 h-0.5 mx-2 rounded', 'bg-muted-foreground/15')} />
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="text-center">
          <Button onClick={onStartEvaluation} size="lg">
            <Play size={16} className="mr-2" /> Start Evaluation
          </Button>
        </div>
      </div>
    )
  }

  // Currently evaluating
  if (isEvaluating) {
    return (
      <div className="space-y-6">
        <div className="w-full max-w-lg mx-auto py-4">
          <div className="flex items-center justify-between">
            {STEPS.map((step, index) => (
              <div key={step.key} className="flex items-center">
                <div className="flex flex-col items-center gap-1.5">
                  <div className={cn(
                    'flex items-center justify-center w-8 h-8 rounded-full transition-all',
                    getCircleBg(index)
                  )}>
                    {getStepIcon(index)}
                  </div>
                  <span className={cn('text-xs transition-colors', getStepStyle(index))}>
                    {step.label}
                  </span>
                </div>
                {index < STEPS.length - 1 && (
                  <div className={cn('w-8 md:w-12 h-0.5 mx-2 rounded', getLineStyle(index))} />
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="text-center">
          <p className="text-sm text-muted-foreground">
            {progress?.step || 'Starting evaluation...'}
          </p>
          <Loader2 size={20} className="mx-auto mt-2 text-primary animate-spin" />
        </div>
      </div>
    )
  }

  // Evaluation complete
  if (evaluated) {
    return (
      <div className="space-y-6">
        <div className="w-full max-w-lg mx-auto py-4">
          <div className="flex items-center justify-between">
            {STEPS.map((step, index) => (
              <div key={step.key} className="flex items-center">
                <div className="flex flex-col items-center gap-1.5">
                  <div className={cn(
                    'flex items-center justify-center w-8 h-8 rounded-full transition-all',
                    'bg-green-100 dark:bg-green-900/30'
                  )}>
                    <Check size={18} className="text-green-500" />
                  </div>
                  <span className="text-xs text-green-600 dark:text-green-400 font-medium">
                    {step.label}
                  </span>
                </div>
                {index < STEPS.length - 1 && (
                  <div className="w-8 md:w-12 h-0.5 mx-2 rounded bg-green-500" />
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="text-center">
          <p className="text-sm text-green-600 font-medium">Evaluation complete!</p>
        </div>
      </div>
    )
  }

  return null
}

import { useState } from 'react'
import { CheckCircle2, AlertCircle, BarChart3, ChevronDown, ChevronUp } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Progress } from '@/components/ui/progress'
import { cn } from '@/lib/utils'
import type { EvaluationResult } from '@/types/api'

interface EvaluationResultsProps {
  result: EvaluationResult | null
  isLoading: boolean
  isEvaluating: boolean
  onOverride?: (criterionName: string, newScore: number) => void
}

function getScoreColor(score: number): string {
  if (score >= 4) return 'text-green-600 bg-green-100 dark:bg-green-900/30 dark:text-green-400'
  if (score >= 2) return 'text-amber-600 bg-amber-100 dark:bg-amber-900/30 dark:text-amber-400'
  return 'text-red-600 bg-red-100 dark:bg-red-900/30 dark:text-red-400'
}

function getProgressColor(value: number): string {
  if (value >= 70) return 'bg-green-500'
  if (value >= 40) return 'bg-amber-500'
  return 'bg-red-500'
}

export default function EvaluationResults({
  result,
  isLoading,
  isEvaluating,
  onOverride,
}: EvaluationResultsProps) {
  const [expandedJustifications, setExpandedJustifications] = useState<Set<number>>(new Set())
  const [editingCriterion, setEditingCriterion] = useState<string | null>(null)
  const [editValue, setEditValue] = useState<number>(0)

  const toggleJustification = (index: number) => {
    setExpandedJustifications((prev) => {
      const next = new Set(prev)
      if (next.has(index)) {
        next.delete(index)
      } else {
        next.add(index)
      }
      return next
    })
  }

  const handleScoreClick = (criterionName: string, currentScore: number) => {
    if (!onOverride) return
    setEditingCriterion(criterionName)
    setEditValue(currentScore)
  }

  const handleScoreConfirm = () => {
    if (!editingCriterion || !onOverride) return
    onOverride(editingCriterion, editValue)
    setEditingCriterion(null)
  }

  const handleScoreCancel = () => {
    setEditingCriterion(null)
  }

  // Loading state
  if (isLoading || isEvaluating) {
    return (
      <div className="space-y-4">
        <Card>
          <CardHeader>
            <Skeleton className="h-6 w-48" />
          </CardHeader>
          <CardContent className="space-y-3">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="flex items-center gap-3">
                <Skeleton className="h-8 w-8 rounded-full" />
                <div className="flex-1 space-y-1">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-48" />
                </div>
                <Skeleton className="h-6 w-10 rounded" />
              </div>
            ))}
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6 text-center">
            <Skeleton className="h-10 w-20 mx-auto mb-2" />
            <Skeleton className="h-4 w-32 mx-auto" />
          </CardContent>
        </Card>
      </div>
    )
  }

  // Empty state
  if (!result) {
    return (
      <Card>
        <CardContent className="p-12 text-center">
          <BarChart3 size={48} className="mx-auto text-muted-foreground/40 mb-4" />
          <h3 className="text-lg font-medium text-foreground mb-1">Evaluation Results</h3>
          <p className="text-sm text-muted-foreground">
            No evaluation results yet. Run evaluation first.
          </p>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-6">
      {/* Aggregate Card */}
      <Card className="border-primary/20">
        <CardContent className="p-6 text-center">
          <div className="text-4xl font-bold text-foreground mb-1">
            {result.aggregate_score.toFixed(1)} <span className="text-2xl text-muted-foreground">/ 5</span>
          </div>
          <div className="flex items-center justify-center gap-2 mb-3">
            <span className="text-lg font-semibold text-muted-foreground">
              {result.aggregate_percentage.toFixed(0)}%
            </span>
            {result.aggregate_percentage >= 70 ? (
              <CheckCircle2 size={18} className="text-green-500" />
            ) : (
              <AlertCircle size={18} className="text-amber-500" />
            )}
          </div>
          <Progress
            value={result.aggregate_percentage}
            className={cn('h-2 max-w-xs mx-auto', getProgressColor(result.aggregate_percentage))}
          />
          <p className="text-xs text-muted-foreground mt-2">
            Rubric: {result.rubric_name}
          </p>
        </CardContent>
      </Card>

      {/* Scores Table */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <BarChart3 size={16} className="text-primary" />
            Criterion Scores
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {result.criteria_scores.map((cs, index) => (
              <div
                key={cs.criterion_name}
                className="rounded-lg border p-3 transition-colors hover:bg-muted/30"
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-medium text-sm">{cs.criterion_name}</span>
                      <span className="text-xs bg-muted px-1.5 py-0.5 rounded text-muted-foreground">
                        {cs.weight}%
                      </span>
                    </div>

                    {/* Justification */}
                    <div className="text-xs text-muted-foreground">
                      {cs.justification.length > 100 ? (
                        <>
                          <span>
                            {expandedJustifications.has(index)
                              ? cs.justification
                              : cs.justification.slice(0, 100) + '...'}
                          </span>
                          <button
                            onClick={() => toggleJustification(index)}
                            className="text-primary hover:underline ml-1 inline-flex items-center gap-0.5"
                          >
                            {expandedJustifications.has(index) ? (
                              <><ChevronUp size={12} /> Less</>
                            ) : (
                              <><ChevronDown size={12} /> More</>
                            )}
                          </button>
                        </>
                      ) : (
                        cs.justification
                      )}
                    </div>
                  </div>

                  {/* Score badge — clickable if onOverride provided */}
                  <div className="flex-shrink-0">
                    {editingCriterion === cs.criterion_name ? (
                      <div className="flex items-center gap-1">
                        <input
                          type="number"
                          min={0}
                          max={5}
                          value={editValue}
                          onChange={(e) => setEditValue(Math.min(5, Math.max(0, parseInt(e.target.value) || 0)))}
                          className="w-14 h-8 text-center rounded border border-input bg-background text-sm font-medium"
                          autoFocus
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleScoreConfirm()
                            if (e.key === 'Escape') handleScoreCancel()
                          }}
                        />
                        <button
                          onClick={handleScoreConfirm}
                          className="text-green-600 hover:text-green-700 text-xs font-medium px-1"
                        >
                          OK
                        </button>
                        <button
                          onClick={handleScoreCancel}
                          className="text-muted-foreground hover:text-foreground text-xs px-1"
                        >
                          X
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={() => handleScoreClick(cs.criterion_name, cs.score)}
                        className={cn(
                          'inline-flex items-center justify-center w-9 h-9 rounded-full text-sm font-bold transition-colors',
                          onOverride ? 'cursor-pointer hover:ring-2 hover:ring-primary' : 'cursor-default',
                          getScoreColor(cs.score)
                        )}
                        title={onOverride ? 'Click to override score' : undefined}
                      >
                        {cs.score}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* AI Summary */}
      {result.ai_summary && (
        <Card className="bg-muted/30">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">AI Summary</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-sm text-muted-foreground whitespace-pre-wrap">
              {result.ai_summary}
            </p>
            <p className="text-xs text-muted-foreground mt-2">
              Evaluated at: {new Date(result.evaluated_at).toLocaleString()}
            </p>
          </CardContent>
        </Card>
      )}

    </div>
  )
}

import { useCallback, useState } from 'react'
