export default function FloatingActionBar({
  comparisonData,
  onReevaluateAll,
  isReevaluatingAll,
}: FloatingActionBarProps) {
  const [exportMode, setExportMode] = useState<'scorecard' | 'detailed' | 'both'>('scorecard')
  const [isExportingZip, setIsExportingZip] = useState(false)
  const [isExportingCsv, setIsExportingCsv] = useState(false)
  const batchSessionId = useBatchStore((s) => s.batchSessionId)

  const completedCount = comparisonData
    ? comparisonData.rows.filter((r) => r.status === 'completed').length
    : 0
  const totalCount = comparisonData?.total ?? 0

  const handleExportZip = useCallback(async () => {
    if (!batchSessionId) return
    setIsExportingZip(true)
    try {
      const url = apiClient.getExportZipUrl(batchSessionId, exportMode)
      apiClient.downloadExport(url, `batch_reports_${batchSessionId.slice(0, 8)}.zip`)
    } catch (err) {
      console.error('ZIP export failed:', err)
    } finally {
      setIsExportingZip(false)
    }
  }, [batchSessionId, exportMode])

  const handleExportCsv = useCallback(async () => {
    if (!batchSessionId) return
    setIsExportingCsv(true)
    try {
      const url = apiClient.getExportCsvUrl(batchSessionId)
      apiClient.downloadExport(url, `batch_scores_${batchSessionId.slice(0, 8)}.csv`)
    } catch (err) {
      console.error('CSV export failed:', err)
    } finally {
      setIsExportingCsv(false)
    }
  }, [batchSessionId])

  const hasCompletedEvaluations = completedCount > 0

  return (
    <div className="sticky bottom-0 z-40 border-t bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between gap-4">
        {/* Left: Status info */}
        <div className="text-sm text-muted-foreground hidden sm:block">
          {comparisonData ? (
            <span>
              <span className="font-medium text-foreground">{completedCount}</span>/{totalCount} evaluated
              {comparisonData.overall_status === 'completed' && (
                <span className="ml-2 text-green-600 dark:text-green-400">All complete</span>
              )}
            </span>
          ) : (
            <span>No evaluation data</span>
          )}
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-2 ml-auto">
          {/* Report mode selector */}
          {hasCompletedEvaluations && (
            <div className="flex items-center gap-1.5">
              <span className="text-xs text-muted-foreground hidden md:inline">Mode:</span>
              <select
                value={exportMode}
                onChange={(e) => setExportMode(e.target.value as typeof exportMode)}
                className="h-8 text-xs border rounded px-2 bg-background"
                aria-label="Report mode"
              >
                <option value="scorecard">Scorecard</option>
                <option value="detailed">Detailed</option>
                <option value="both">Both</option>
              </select>
            </div>
          )}

          {/* Export CSV */}
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportCsv}
            disabled={!hasCompletedEvaluations || isExportingCsv}
            className="gap-1.5 whitespace-nowrap"
          >
            <FileSpreadsheet size={14} />
            <span className="hidden sm:inline">CSV</span>
          </Button>

          {/* Export ZIP */}
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportZip}
            disabled={!hasCompletedEvaluations || isExportingZip}
            className="gap-1.5 whitespace-nowrap"
          >
            {isExportingZip ? (
              <RefreshCw size={14} className="animate-spin" />
            ) : (
              <FileArchive size={14} />
            )}
            <span className="hidden sm:inline">PDFs</span>
          </Button>

          {/* Re-evaluate All */}
          <Button
            variant="default"
            size="sm"
            onClick={onReevaluateAll}
            disabled={!hasCompletedEvaluations || isReevaluatingAll}
            className="gap-1.5 whitespace-nowrap"
          >
            {isReevaluatingAll ? (
              <RefreshCw size={14} className="animate-spin" />
            ) : (
              <RotateCcw size={14} />
            )}
            <span className="hidden sm:inline">Re-evaluate All</span>
          </Button>
        </div>
      </div>
    </div>
  )
}

import { useMemo } from 'react'
import { FileText, Play, AlertCircle, ChevronRight, Sparkles } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { sanitizeOutput } from '@/lib/sanitize'
import type { ParsedCell, NotebookOutput } from '@/types/api'

interface NotebookPreviewProps {
  cells: ParsedCell[]
  onAnalyze: () => void
  isAnalyzing: boolean
}

export default function NotebookPreview({ cells, onAnalyze, isAnalyzing }: NotebookPreviewProps) {
  const stats = useMemo(() => {
    const code = cells.filter((c) => c.cell_type === 'code').length
    const markdown = cells.filter((c) => c.cell_type === 'markdown').length
    const raw = cells.filter((c) => c.cell_type === 'raw').length
    const errors = cells.filter((c) => c.has_error).length
    return { total: cells.length, code, markdown, raw, errors }
  }, [cells])

  const renderSource = (cell: ParsedCell): string => {
    switch (cell.cell_type) {
      case 'markdown':
        return sanitizeOutput(cell.source)
      case 'code':
      case 'raw':
      default:
        return cell.source
    }
  }

  const renderOutputs = (cell: ParsedCell) => {
    if (!cell.outputs || cell.outputs.length === 0) return null

    return (
      <div className="mt-2 space-y-1">
        {cell.outputs.map((output, oi) => {
          const outputText = extractOutputText(output)
          if (!outputText) return null

          const sanitized = sanitizeOutput(outputText)

          if (output.output_type === 'error') {
            return (
              <div
                key={oi}
                className="bg-red-50 dark:bg-red-950/30 border-l-2 border-red-500 p-2 rounded text-xs font-mono text-red-700 dark:text-red-300 whitespace-pre-wrap overflow-x-auto"
              >
                {output.ename && (
                  <span className="font-bold">{output.ename}: </span>
                )}
                {output.evalue && <span>{output.evalue}</span>}
                {sanitized && !output.ename && !output.evalue && <span>{sanitized}</span>}
              </div>
            )
          }

          return (
            <pre
              key={oi}
              className="bg-gray-100 dark:bg-gray-800/50 border-l-2 border-gray-300 dark:border-gray-600 p-2 rounded text-xs font-mono text-gray-700 dark:text-gray-300 whitespace-pre-wrap overflow-x-auto"
            >
              {sanitized}
            </pre>
          )
        })}
      </div>
    )
  }

  if (cells.length === 0) {
    return (
      <Card>
        <CardContent className="p-12 text-center">
          <FileText size={48} className="mx-auto text-muted-foreground/40 mb-4" />
          <h3 className="text-lg font-medium text-foreground mb-1">No Cells Found</h3>
          <p className="text-sm text-muted-foreground">
            This notebook appears to have no cells. Try uploading a different file.
          </p>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-6">
      {/* Notebook header with stats */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <FileText size={20} className="text-primary" />
            Notebook Preview
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-3 text-sm">
            <span className="text-muted-foreground">
              <strong className="text-foreground">{stats.total}</strong> cells
            </span>
            <span className="text-muted-foreground">·</span>
            <span className="text-blue-600 dark:text-blue-400">
              <strong>{stats.code}</strong> code
            </span>
            <span className="text-muted-foreground">·</span>
            <span className="text-green-600 dark:text-green-400">
              <strong>{stats.markdown}</strong> markdown
            </span>
            {stats.raw > 0 && (
              <>
                <span className="text-muted-foreground">·</span>
                <span className="text-muted-foreground">
                  <strong>{stats.raw}</strong> raw
                </span>
              </>
            )}
            {stats.errors > 0 && (
              <>
                <span className="text-muted-foreground">·</span>
                <span className="text-red-600 dark:text-red-400">
                  <strong>{stats.errors}</strong> error{stats.errors > 1 ? 's' : ''}
                </span>
              </>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Cell-by-cell preview */}
      <div className="max-h-[600px] overflow-y-auto space-y-2 rounded-lg border bg-card p-1">
        {cells.map((cell, index) => (
          <CellRenderer key={index} cell={cell} index={index} source={renderSource(cell)}>
            {renderOutputs(cell)}
          </CellRenderer>
        ))}
      </div>

      {/* Analyze button */}
      <div className="flex justify-center pt-2">
        <Button
          onClick={onAnalyze}
          disabled={isAnalyzing}
          size="lg"
          className="gap-2 px-8"
        >
          {isAnalyzing ? (
            <>
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
              Analyzing...
            </>
          ) : (
            <>
              <Sparkles size={20} />
              Analyze with AI
            </>
          )}
        </Button>
      </div>
    </div>
  )
}

interface CellRendererProps {
  cell: ParsedCell
  index: number
  source: string
  children: React.ReactNode
}

function CellRenderer({ cell, index, source, children }: CellRendererProps) {
  const isCode = cell.cell_type === 'code'
  const isMarkdown = cell.cell_type === 'markdown'
  const hasError = cell.has_error

  return (
    <div
      className={cn(
        'rounded-md border transition-colors',
        isCode && 'border-blue-200 dark:border-blue-900/50',
        isMarkdown && 'border-green-200 dark:border-green-900/50',
        !isCode && !isMarkdown && 'border-gray-200 dark:border-gray-700',
        hasError && 'border-red-300 dark:border-red-900/50 bg-red-50/30 dark:bg-red-950/20'
      )}
    >
      {/* Cell header */}
      <div
        className={cn(
          'flex items-center gap-2 px-3 py-1.5 text-xs font-medium border-b',
          isCode && 'bg-blue-50 dark:bg-blue-950/30 border-blue-200 dark:border-blue-900/50 text-blue-700 dark:text-blue-300',
          isMarkdown && 'bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-900/50 text-green-700 dark:text-green-300',
          !isCode && !isMarkdown && 'bg-gray-50 dark:bg-gray-800/30 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400',
          hasError && 'bg-red-50 dark:bg-red-950/30 border-red-300 dark:border-red-900/50 text-red-700 dark:text-red-300'
        )}
      >
        {isCode && <Play size={12} />}
        {isMarkdown && <ChevronRight size={12} />}
        {hasError && <AlertCircle size={12} />}
        <span>{cell.cell_type.toUpperCase()}</span>
        {cell.execution_count != null && (
          <span className="ml-auto text-muted-foreground">[ {cell.execution_count} ]</span>
        )}
        <span className="ml-auto text-muted-foreground/60">#{index + 1}</span>
      </div>

      {/* Cell content */}
      <div className="px-3 py-2">
        {isCode ? (
          <pre className="text-sm font-mono text-foreground whitespace-pre-wrap overflow-x-auto leading-relaxed">
            {source}
          </pre>
        ) : isMarkdown ? (
          <div className="text-sm text-foreground prose-sm max-w-none">
            {renderSimpleMarkdown(source)}
          </div>
        ) : (
          <pre className="text-sm font-mono text-muted-foreground whitespace-pre-wrap overflow-x-auto">
            {source}
          </pre>
        )}

        {/* Outputs for code cells */}
        {children}
      </div>
    </div>
  )
}

function extractOutputText(output: NotebookOutput): string {
  if (output.text) {
    if (Array.isArray(output.text)) return output.text.join('')
    return output.text
  }
  if (output.traceback && Array.isArray(output.traceback)) {
    return output.traceback.join('\n')
  }
  if (output.data && typeof output.data === 'object') {
    const data = output.data as Record<string, unknown>
    if (typeof data['text/plain'] === 'string') return data['text/plain']
    if (Array.isArray(data['text/plain'])) return (data['text/plain'] as string[]).join('')
  }
  return ''
}

/**
 * Simple markdown renderer for notebook markdown cells.
 * Handles basic formatting: bold, italic, inline code, headings, lists.
 */
function renderSimpleMarkdown(text: string): React.ReactNode {
  if (!text) return null

  // Split into paragraphs
  const paragraphs = text.split(/\n\s*\n/)

  return (
    <>
      {paragraphs.map((para, pi) => {
        const trimmed = para.trim()
        if (!trimmed) return null

        // Heading detection
        if (trimmed.startsWith('### ')) {
          return <h3 key={pi} className="text-base font-semibold mt-4 mb-1">{renderInline(trimmed.slice(4))}</h3>
        }
        if (trimmed.startsWith('## ')) {
          return <h2 key={pi} className="text-lg font-semibold mt-4 mb-1">{renderInline(trimmed.slice(3))}</h2>
        }
        if (trimmed.startsWith('# ')) {
          return <h1 key={pi} className="text-xl font-bold mt-4 mb-2">{renderInline(trimmed.slice(2))}</h1>
        }

        // List item detection
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
          const items = trimmed.split('\n').filter((l) => l.trim().startsWith('- ') || l.trim().startsWith('* '))
          return (
            <ul key={pi} className="list-disc pl-5 my-1 space-y-0.5">
              {items.map((item, ii) => (
                <li key={ii}>{renderInline(item.replace(/^[-*]\s+/, ''))}</li>
              ))}
            </ul>
          )
        }

        // Numbered list detection
        if (/^\d+\.\s/.test(trimmed)) {
          const items = trimmed.split('\n').filter((l) => /^\d+\.\s/.test(l.trim()))
          return (
            <ol key={pi} className="list-decimal pl-5 my-1 space-y-0.5">
              {items.map((item, ii) => (
                <li key={ii}>{renderInline(item.replace(/^\d+\.\s+/, ''))}</li>
              ))}
            </ol>
          )
        }

        // Regular paragraph with line breaks
        return (
          <p key={pi} className="my-1 leading-relaxed">
            {trimmed.split('\n').map((line, li) => (
              <span key={li}>
                {li > 0 && <br />}
                {renderInline(line)}
              </span>
            ))}
          </p>
        )
      })}
    </>
  )
}

/**
 * Simple inline formatting: bold, italic, inline code.
 */
function renderInline(text: string): React.ReactNode {
  if (!text) return null

  // Simple parser for inline formatting
  const parts: React.ReactNode[] = []
  let remaining = text
  let key = 0

  while (remaining.length > 0) {
    // Inline code: `code`
    const codeMatch = remaining.match(/`([^`]+)`/)
    if (codeMatch && codeMatch.index !== undefined) {
      if (codeMatch.index > 0) {
        parts.push(renderBoldItalic(remaining.slice(0, codeMatch.index), key++))
      }
      parts.push(
        <code key={`code-${key++}`} className="bg-muted px-1 py-0.5 rounded text-sm font-mono text-primary">
          {codeMatch[1]}
        </code>
      )
      remaining = remaining.slice(codeMatch.index! + codeMatch[0].length)
      continue
    }

    // No more special formatting
    parts.push(renderBoldItalic(remaining, key++))
    remaining = ''
  }

  return parts
}

function renderBoldItalic(text: string, key: number): React.ReactNode {
  if (!text) return null

  // Bold: **text** or __text__
  const boldMatch = text.match(/(\*\*|__)(.*?)\1/)
  if (boldMatch && boldMatch.index !== undefined) {
    const before = text.slice(0, boldMatch.index!)
    const boldText = boldMatch[2]
    const after = text.slice(boldMatch.index! + boldMatch[0].length)
    return (
      <span key={key}>
        {renderItalic(before)}
        <strong className="font-semibold">{renderItalic(boldText)}</strong>
        {renderBoldItalic(after, key + 1)}
      </span>
    )
  }

  return renderItalic(text)
}

function renderItalic(text: string): React.ReactNode {
  if (!text) return null

  const italicMatch = text.match(/(\*|_)(.*?)\1/)
  if (italicMatch && italicMatch.index !== undefined) {
    const before = text.slice(0, italicMatch.index!)
    const italicText = italicMatch[2]
    const after = text.slice(italicMatch.index! + italicMatch[0].length)
    return (
      <span key={0}>
        {before}
        <em>{italicText}</em>
        {renderItalic(after)}
      </span>
    )
  }

  return text
}

import { Loader2, CheckCircle2, Circle } from 'lucide-react'
import { cn } from '@/lib/utils'

export type StageStatus = 'idle' | 'uploading' | 'validating' | 'parsing' | 'ready'

interface ProgressIndicatorProps {
  currentStage: string
  stages?: string[]
}

const defaultStages = ['uploading', 'validating', 'parsing', 'ready']

const stageLabels: Record<string, string> = {
  idle: 'Idle',
  uploading: 'Uploading',
  validating: 'Validating',
  parsing: 'Parsing',
  ready: 'Ready',
}

export default function ProgressIndicator({ currentStage, stages = defaultStages }: ProgressIndicatorProps) {
  if (currentStage === 'idle') return null

  const currentIndex = stages.indexOf(currentStage)

  if (currentIndex === -1) return null

  const getStageIcon = (_stage: string, index: number) => {
    if (index < currentIndex) {
      return <CheckCircle2 size={18} className="text-green-500" />
    }
    if (index === currentIndex) {
      return <Loader2 size={18} className="text-primary animate-spin" />
    }
    return <Circle size={18} className="text-muted-foreground/40" />
  }

  const getStageStyle = (index: number) => {
    if (index < currentIndex) return 'text-green-600 dark:text-green-400'
    if (index === currentIndex) return 'text-primary font-medium'
    return 'text-muted-foreground/50'
  }

  const getLineStyle = (index: number) => {
    if (index < currentIndex) return 'bg-green-500'
    if (index === currentIndex) return 'bg-primary/30'
    return 'bg-muted-foreground/15'
  }

  return (
    <div className="w-full max-w-lg mx-auto py-4">
      <div className="flex items-center justify-between">
        {stages.map((stage, index) => (
          <div key={stage} className="flex items-center">
            {/* Stage circle + label */}
            <div className="flex flex-col items-center gap-1.5">
              <div className={cn(
                'flex items-center justify-center w-8 h-8 rounded-full transition-all',
                index < currentIndex && 'bg-green-100 dark:bg-green-900/30',
                index === currentIndex && 'bg-primary/10',
                index > currentIndex && 'bg-muted/30'
              )}>
                {getStageIcon(stage, index)}
              </div>
              <span className={cn(
                'text-xs transition-colors',
                getStageStyle(index)
              )}>
                {stageLabels[stage] || stage}
              </span>
            </div>

            {/* Connecting line */}
            {index < stages.length - 1 && (
              <div className={cn(
                'w-8 md:w-12 h-0.5 mx-2 rounded transition-colors',
                getLineStyle(index)
              )} />
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { Check, Plus, Trash2, Sparkles, FileText, Pencil } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { useRubric } from '@/hooks/useRubric'
import { apiClient } from '@/services/api'
import { useSessionStore } from '@/stores/sessionStore'
import type { RubricTemplate, Criterion } from '@/types/api'

interface RubricSelectorProps {
  onRubricReady: (rubric: RubricTemplate) => void
  initialRubric?: RubricTemplate | null
}

type RubricMode = 'select' | 'custom'

export default function RubricSelector({ onRubricReady, initialRubric }: RubricSelectorProps) {
  const {
    templates,
    isLoading,
    error,
    customCriteria,
    loadTemplates,
    selectTemplate,
    addCustomCriterion,
    removeCustomCriterion,
    setCustomCriteria,
    setSelectedTemplate,
  } = useRubric()

  const [mode, setMode] = useState<RubricMode>(initialRubric ? 'select' : 'select')
  const [rubricName, setRubricName] = useState(initialRubric?.name || '')
  const [selectedTemplateName, setSelectedTemplateName] = useState<string | null>(
    initialRubric?.name || null
  )
  const [templateCriteria, setTemplateCriteria] = useState<Criterion[]>(
    initialRubric?.criteria || []
  )
  const [templateExpanded, setTemplateExpanded] = useState<string | null>(
    initialRubric?.name || null
  )

  useEffect(() => {
    loadTemplates()
  }, [loadTemplates])

  // Pre-populate from initialRubric
  useEffect(() => {
    if (initialRubric) {
      setRubricName(initialRubric.name)
      setSelectedTemplateName(initialRubric.name)
      setTemplateCriteria(initialRubric.criteria)
    }
  }, [initialRubric])

  const handleSelectTemplate = (name: string) => {
    selectTemplate(name)
    setSelectedTemplateName(name)
    setTemplateExpanded(name === templateExpanded ? null : name)

    // Load actual criteria from backend templates
    if (templates) {
      const summary = templates.find((t) => t.name === name)
      if (summary?.criteria) {
        setTemplateCriteria(summary.criteria)
      }
    }
  }

  const handleCustomize = () => {
    setMode('custom')
    if (selectedTemplateName && templateCriteria.length > 0) {
      setCustomCriteria(templateCriteria)
    }
  }

  const handleUseTemplate = async () => {
    if (!selectedTemplateName) return
    const rubric: RubricTemplate = {
      name: selectedTemplateName,
      criteria: templateCriteria,
    }
    setSelectedTemplate(rubric)
    setSelectedTemplateName(selectedTemplateName)
    try {
      const sessionId = useSessionStore.getState().sessionId
      if (sessionId) {
        await apiClient.saveRubric(rubric, sessionId)
      }
    } catch (e) {
      // API error — still notify parent so evaluation can proceed
    }
    onRubricReady(rubric)
  }

  const handleAddCriterion = () => {
    addCustomCriterion({
      name: '',
      description: '',
      weight: 10,
      pass_condition: '>= 3',
    })
  }

  const handleUpdateCriterion = (index: number, field: keyof Criterion, value: string | number) => {
    const updated = customCriteria.map((c, i) => {
      if (i === index) {
        return { ...c, [field]: value }
      }
      return c
    })
    setCustomCriteria(updated)
  }

  const handleRemoveCriterion = (index: number) => {
    removeCustomCriterion(index)
  }

  const handleSaveCustom = async () => {
    if (!rubricName.trim()) return

    setSelectedTemplateName(rubricName)
    setSelectedTemplate({
      name: rubricName,
      criteria: customCriteria,
    })

    // Normalize weights for backend
    const totalWeight = customCriteria.reduce((sum, c) => sum + c.weight, 0)
    const factor = totalWeight > 0 ? 100 / totalWeight : 1
    const rubric: RubricTemplate = {
      name: rubricName,
      criteria: customCriteria.map((c) => ({
        ...c,
        weight: Math.round(c.weight * factor),
      })),
    }

    // Save directly to avoid stale closure on hook's saveRubric
    try {
      const sessionId = useSessionStore.getState().sessionId
      if (sessionId) {
        await apiClient.saveRubric(rubric, sessionId)
      }
    } catch (e) {
      // API error — still notify parent
    }

    onRubricReady(rubric)
  }

  const totalCustomWeight = customCriteria.reduce((sum, c) => sum + (c.weight || 0), 0)
  const weightValid = totalCustomWeight === 100

  // Loading state
  if (isLoading && !templates) {
    return (
      <div className="space-y-6">
        <div className="grid gap-4 md:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <Card key={i}>
              <CardContent className="p-6">
                <Skeleton className="h-5 w-32 mb-3" />
                <Skeleton className="h-4 w-20 mb-4" />
                <Skeleton className="h-9 w-full" />
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    )
  }

  // Error state
  if (error) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <p className="text-destructive font-medium mb-2">Failed to load rubric templates</p>
          <p className="text-sm text-muted-foreground mb-4">{error.message}</p>
          <Button onClick={loadTemplates} variant="outline">Retry</Button>
        </CardContent>
      </Card>
    )
  }

  // Custom builder mode
  if (mode === 'custom') {
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-3 mb-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setMode('select')}
          >
            ← Back to Templates
          </Button>
          <h3 className="text-lg font-semibold">Custom Rubric</h3>
        </div>

        {/* Rubric name */}
        <div>
          <label className="block text-sm font-medium mb-1">Rubric Name</label>
          <input
            type="text"
            value={rubricName}
            onChange={(e) => setRubricName(e.target.value)}
            placeholder="e.g., Data Science Project Evaluation"
            className="w-full px-3 py-2 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring"
          />
        </div>

        {/* Criteria list */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-medium">Criteria ({customCriteria.length})</h4>
            <Button size="sm" variant="outline" onClick={handleAddCriterion}>
              <Plus size={14} className="mr-1" /> Add Criterion
            </Button>
          </div>

          {customCriteria.length === 0 && (
            <Card>
              <CardContent className="p-8 text-center">
                <FileText size={32} className="mx-auto text-muted-foreground/40 mb-2" />
                <p className="text-sm text-muted-foreground">
                  No criteria defined. Click "Add Criterion" to start building your rubric.
                </p>
              </CardContent>
            </Card>
          )}

          {customCriteria.map((criterion, index) => (
            <Card key={index} className="relative">
              <CardContent className="p-4 space-y-3">
                <div className="flex items-start justify-between">
                  <span className="text-xs font-medium text-muted-foreground">Criterion #{index + 1}</span>
                  <Button
                    size="sm"
                    variant="ghost"
                    className="text-destructive h-8 w-8 p-0"
                    onClick={() => handleRemoveCriterion(index)}
                    disabled={customCriteria.length <= 1}
                  >
                    <Trash2 size={14} />
                  </Button>
                </div>

                <div className="grid gap-3 md:grid-cols-2">
                  <div>
                    <label className="block text-xs font-medium mb-1">Name</label>
                    <input
                      type="text"
                      value={criterion.name}
                      onChange={(e) => handleUpdateCriterion(index, 'name', e.target.value)}
                      placeholder="Criterion name"
                      className="w-full px-2 py-1.5 rounded border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium mb-1">Weight (%)</label>
                    <input
                      type="number"
                      min={1}
                      max={100}
                      value={criterion.weight}
                      onChange={(e) => handleUpdateCriterion(index, 'weight', parseInt(e.target.value) || 0)}
                      className="w-full px-2 py-1.5 rounded border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium mb-1">Description</label>
                  <textarea
                    value={criterion.description}
                    onChange={(e) => handleUpdateCriterion(index, 'description', e.target.value)}
                    placeholder="What does this criterion evaluate?"
                    rows={2}
                    className="w-full px-2 py-1.5 rounded border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring resize-none"
                  />
                </div>

                <div>
                  <label className="block text-xs font-medium mb-1">Pass Condition</label>
                  <input
                    type="text"
                    value={criterion.pass_condition}
                    onChange={(e) => handleUpdateCriterion(index, 'pass_condition', e.target.value)}
                    placeholder="e.g., >= 3"
                    className="w-full px-2 py-1.5 rounded border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                  />
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Weight validation */}
        {customCriteria.length > 0 && (
          <div className="flex items-center gap-2 text-sm">
            <span className="text-muted-foreground">Total weight:</span>
            <span className={weightValid ? 'text-green-600 font-medium' : 'text-destructive font-medium'}>
              {totalCustomWeight}%
            </span>
            {weightValid ? (
              <Check size={14} className="text-green-500" />
            ) : (
              <span className="text-xs text-destructive">(must sum to 100%)</span>
            )}
          </div>
        )}

        <Button
          onClick={handleSaveCustom}
          disabled={!rubricName.trim() || customCriteria.length === 0 || isLoading}
          className="w-full"
        >
          {isLoading ? 'Saving...' : 'Save Rubric'}
        </Button>
      </div>
    )
  }

  // Template selection mode
  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold mb-1">Select Rubric Template</h3>
        <p className="text-sm text-muted-foreground">
          Choose a pre-built template or create a custom rubric for evaluation.
        </p>
      </div>

      {/* Template cards */}
      <div className="grid gap-4 md:grid-cols-3">
        {(templates || []).length === 0 && !isLoading && (
          <>
            {/* Fallback template cards if API not yet available */}
            {['Generic Notebook', 'DS Project', 'ML Project'].map((name) => (
              <Card
                key={name}
                className={`cursor-pointer transition-all hover:border-primary/50 ${
                  selectedTemplateName === name ? 'ring-2 ring-primary border-primary bg-primary/5' : ''
                }`}
                onClick={() => handleSelectTemplate(name)}
              >
                <CardContent className="p-5">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={18} className="text-primary" />
                    <h4 className="font-medium">{name}</h4>
                  </div>
                  <p className="text-xs text-muted-foreground mb-3">
                    {name === 'Generic Notebook' ? 'General-purpose notebook evaluation' :
                     name === 'DS Project' ? 'Data science project evaluation' :
                     'Machine learning project evaluation'}
                  </p>
                  <span className="text-xs text-muted-foreground">
                    {name === 'Generic Notebook' ? '4 criteria' :
                     name === 'DS Project' ? '6 criteria' :
                     '6 criteria'}
                  </span>
                  {selectedTemplateName === name && (
                    <div className="mt-2">
                      <span className="inline-flex items-center gap-1 text-xs text-primary font-medium">
                        <Check size={12} /> Selected
                      </span>
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </>
        )}

        {/* Templates from API */}
        {templates?.map((template) => (
          <Card
            key={template.name}
            className={`cursor-pointer transition-all hover:border-primary/50 ${
              selectedTemplateName === template.name ? 'ring-2 ring-primary border-primary bg-primary/5' : ''
            }`}
            onClick={() => handleSelectTemplate(template.name)}
          >
            <CardContent className="p-5">
              <div className="flex items-center gap-2 mb-2">
                <Sparkles size={18} className="text-primary" />
                <h4 className="font-medium">{template.name}</h4>
              </div>
              <p className="text-xs text-muted-foreground mb-3">
                {template.criteria_count} criteria
              </p>
              {selectedTemplateName === template.name && (
                <span className="inline-flex items-center gap-1 text-xs text-primary font-medium">
                  <Check size={12} /> Selected
                </span>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Selected template criteria */}
      {selectedTemplateName && mode === 'select' && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2">
              <FileText size={16} className="text-primary" />
              {selectedTemplateName} — Criteria
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {templateCriteria.map((criterion, i) => (
                <div key={i} className="flex items-center justify-between py-2 px-3 rounded bg-muted/50">
                  <div>
                    <span className="text-sm font-medium">{criterion.name}</span>
                    <p className="text-xs text-muted-foreground">{criterion.description}</p>
                  </div>
                  <span className="text-xs font-medium text-muted-foreground whitespace-nowrap ml-2">
                    Weight: {criterion.weight}%
                  </span>
                </div>
              ))}
            </div>

            <div className="flex gap-3 mt-4">
              <Button onClick={handleUseTemplate}>
                <Check size={14} className="mr-1" /> Use Template
              </Button>
              <Button variant="outline" onClick={handleCustomize}>
                <Pencil size={14} className="mr-1" /> Customize
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Custom option */}
      {!selectedTemplateName && (
        <div className="text-center">
          <Button variant="outline" onClick={() => setMode('custom')}>
            <Plus size={14} className="mr-1" /> Create Custom Rubric
          </Button>
        </div>
      )}
    </div>
  )
}

import { useState, useMemo, useEffect } from 'react'
import { RotateCcw, AlertTriangle, CheckCircle2, AlertCircle, PenLine, X } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Progress } from '@/components/ui/progress'
import { cn } from '@/lib/utils'
import type { EvaluationResult, ScoreOverride as ScoreOverrideType } from '@/types/api'

interface ScoreOverrideProps {
  evaluationResult: EvaluationResult
  overrides: ScoreOverrideType[]
  onOverride: (criterionName: string, newScore: number, reason: string) => void
  onResetOverride: (criterionName: string) => void
}

function getScoreColor(score: number): string {
  if (score >= 4) return 'text-green-600 bg-green-100 dark:bg-green-900/30 dark:text-green-400'
  if (score >= 2) return 'text-amber-600 bg-amber-100 dark:bg-amber-900/30 dark:text-amber-400'
  return 'text-red-600 bg-red-100 dark:bg-red-900/30 dark:text-red-400'
}

export default function ScoreOverride({
  evaluationResult,
  overrides,
  onOverride,
  onResetOverride,
}: ScoreOverrideProps) {
  const [editingCriterion, setEditingCriterion] = useState<string | null>(null)
  const [editValue, setEditValue] = useState<number>(0)
  const [reasonModal, setReasonModal] = useState<{
    criterionName: string
    newScore: number
  } | null>(null)
  const [reasonText, setReasonText] = useState('')
  const [reasonError, setReasonError] = useState('')

  // Compute original aggregate
  const originalAggregate = useMemo(() => {
    return evaluationResult.aggregate_score
  }, [evaluationResult])

  // Compute adjusted aggregate
  const adjustedAggregate = useMemo(() => {
    const totalWeight = evaluationResult.criteria_scores.reduce((sum, cs) => sum + cs.weight, 0)
    if (totalWeight === 0) return 0

    let weightedSum = 0
    for (const cs of evaluationResult.criteria_scores) {
      const override = overrides.find((o) => o.criterion_name === cs.criterion_name)
      const score = override ? override.overridden_score : cs.score
      weightedSum += score * cs.weight
    }
    return weightedSum / totalWeight
  }, [evaluationResult, overrides])

  const adjustedPercentage = useMemo(() => {
    return (adjustedAggregate / 5) * 100
  }, [adjustedAggregate])

  const getEffectiveScore = (criterionName: string): number => {
    const override = overrides.find((o) => o.criterion_name === criterionName)
    if (override) return override.overridden_score
    const cs = evaluationResult.criteria_scores.find((c) => c.criterion_name === criterionName)
    return cs?.score ?? 0
  }

  const getOriginalScore = (criterionName: string): number => {
    const cs = evaluationResult.criteria_scores.find((c) => c.criterion_name === criterionName)
    return cs?.score ?? 0
  }

  const isOverridden = (criterionName: string): boolean => {
    return overrides.some((o) => o.criterion_name === criterionName)
  }

  const getOverrideReason = (criterionName: string): string | undefined => {
    return overrides.find((o) => o.criterion_name === criterionName)?.reason
  }

  const handleScoreClick = (criterionName: string) => {
    setEditingCriterion(criterionName)
    setEditValue(getEffectiveScore(criterionName))
  }

  const handleScoreConfirm = (criterionName: string) => {
    if (editValue < 0 || editValue > 5) return
    // Open the reason modal instead of directly overriding
    setReasonModal({ criterionName, newScore: editValue })
    setEditingCriterion(null)
    setReasonText('')
    setReasonError('')
  }

  const handleScoreCancel = () => {
    setEditingCriterion(null)
  }

  const handleReasonConfirm = () => {
    if (!reasonModal) return

    if (!reasonText.trim()) {
      setReasonError('Reason is required for score override.')
      return
    }

    onOverride(reasonModal.criterionName, reasonModal.newScore, reasonText.trim())
    setReasonModal(null)
    setReasonText('')
    setReasonError('')
  }

  const handleReasonCancel = () => {
    setReasonModal(null)
    setReasonText('')
    setReasonError('')
  }

  // Close on Escape key
  useEffect(() => {
    if (!reasonModal) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') handleReasonCancel() }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [reasonModal])

  const handleKeyDown = (e: React.KeyboardEvent, criterionName: string) => {
    if (e.key === 'Enter') {
      handleScoreConfirm(criterionName)
    } else if (e.key === 'Escape') {
      handleScoreCancel()
    }
  }

  return (
    <div className="space-y-6">
      {/* Aggregate comparison */}
      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <CardContent className="p-4 text-center">
            <p className="text-xs text-muted-foreground mb-1">Original Score</p>
            <p className="text-2xl font-bold text-muted-foreground">
              {originalAggregate.toFixed(1)}
            </p>
          </CardContent>
        </Card>
        <Card className={cn(
          overrides.length > 0 ? 'border-primary/30' : ''
        )}>
          <CardContent className="p-4 text-center">
            <p className="text-xs text-muted-foreground mb-1">
              Current Score
              {overrides.length > 0 && (
                <span className="text-primary font-medium"> (with overrides)</span>
              )}
            </p>
            <p className="text-2xl font-bold text-foreground">
              {adjustedAggregate.toFixed(1)}
            </p>
            <div className="flex items-center justify-center gap-1 mt-1">
              <span className="text-xs text-muted-foreground">
                {adjustedPercentage.toFixed(0)}%
              </span>
              {adjustedPercentage >= 70 ? (
                <CheckCircle2 size={14} className="text-green-500" />
              ) : (
                <AlertCircle size={14} className="text-amber-500" />
              )}
            </div>
            {overrides.length > 0 && (
              <Progress
                value={adjustedPercentage}
                className="h-1.5 mt-2 max-w-[80%] mx-auto"
              />
            )}
          </CardContent>
        </Card>
      </div>

      {/* Scores table */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <PenLine size={16} className="text-primary" />
            Review & Override Scores
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {evaluationResult.criteria_scores.map((cs) => {
              const effectiveScore = getEffectiveScore(cs.criterion_name)
              const origScore = getOriginalScore(cs.criterion_name)
              const overridden = isOverridden(cs.criterion_name)
              const reason = getOverrideReason(cs.criterion_name)

              return (
                <div
                  key={cs.criterion_name}
                  className={cn(
                    'rounded-lg border p-3 transition-colors',
                    overridden ? 'border-primary/30 bg-primary/5' : 'hover:bg-muted/30'
                  )}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium text-sm">{cs.criterion_name}</span>
                        <span className="text-xs bg-muted px-1.5 py-0.5 rounded text-muted-foreground">
                          {cs.weight}%
                        </span>
                        {overridden && (
                          <span className="inline-flex items-center gap-0.5 text-xs text-primary font-medium">
                            <PenLine size={10} /> Override
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {cs.justification}
                      </p>
                      {overridden && reason && (
                        <p className="text-xs text-muted-foreground mt-1 italic">
                          Reason: {reason}
                        </p>
                      )}
                    </div>

                    <div className="flex-shrink-0 flex items-center gap-1">
                      {editingCriterion === cs.criterion_name ? (
                        <div className="flex items-center gap-1">
                          <input
                            type="number"
                            min={0}
                            max={5}
                            value={editValue}
                            onChange={(e) => setEditValue(Math.min(5, Math.max(0, parseInt(e.target.value) || 0)))}
                            className="w-14 h-8 text-center rounded border border-input bg-background text-sm font-medium"
                            autoFocus
                            onKeyDown={(e) => handleKeyDown(e, cs.criterion_name)}
                          />
                          <button
                            onClick={() => handleScoreConfirm(cs.criterion_name)}
                            className="text-green-600 hover:text-green-700 text-xs font-medium px-1"
                          >
                            OK
                          </button>
                          <button
                            onClick={handleScoreCancel}
                            className="text-muted-foreground hover:text-foreground text-xs px-1"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      ) : (
                        <>
                          <button
                            onClick={() => handleScoreClick(cs.criterion_name)}
                            className={cn(
                              'inline-flex items-center justify-center w-9 h-9 rounded-full text-sm font-bold transition-all cursor-pointer hover:ring-2 hover:ring-primary',
                              getScoreColor(effectiveScore)
                            )}
                            title="Click to override"
                          >
                            {effectiveScore}
                          </button>
                          {overridden && (
                            <button
                              onClick={() => onResetOverride(cs.criterion_name)}
                              className="text-muted-foreground hover:text-foreground p-1"
                              title="Reset to original score"
                            >
                              <RotateCcw size={14} />
                            </button>
                          )}
                        </>
                      )}
                    </div>
                  </div>

                  {/* Show original vs override comparison */}
                  {overridden && (
                    <div className="mt-1 text-xs text-muted-foreground">
                      Original: <span className={cn('font-medium', getScoreColor(origScore))}>{origScore}</span>
                      {' → '}
                      Override: <span className={cn('font-medium', getScoreColor(effectiveScore))}>{effectiveScore}</span>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </CardContent>
      </Card>

      {/* Override summary */}
      {overrides.length > 0 && (
        <Card className="bg-muted/30">
          <CardContent className="p-4">
            <p className="text-sm font-medium flex items-center gap-1">
              <AlertTriangle size={14} className="text-amber-500" />
              {overrides.length} score override{overrides.length > 1 ? 's' : ''} applied
            </p>
            <p className="text-xs text-muted-foreground mt-1">
              Override reasons will be included in the PDF report.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Mandatory Reason Modal */}
      {reasonModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
          onClick={handleReasonCancel}
          onKeyDown={(e) => { if (e.key === 'Escape') handleReasonCancel() }}
        >
          <Card className="w-full max-w-md mx-4" onClick={(e) => e.stopPropagation()}>
            <CardHeader>
              <CardTitle className="text-base">Reason for Override</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <p className="text-sm text-muted-foreground mb-1">
                  Criterion: <span className="font-medium text-foreground">{reasonModal.criterionName}</span>
                </p>
                <p className="text-sm text-muted-foreground mb-3">
                  New score: <span className="font-medium text-foreground">{reasonModal.newScore}/5</span>
                </p>
                <label className="block text-sm font-medium mb-1">
                  Reason for override <span className="text-destructive">*</span>
                </label>
                <textarea
                  value={reasonText}
                  onChange={(e) => {
                    setReasonText(e.target.value)
                    if (reasonError) setReasonError('')
                  }}
                  placeholder="Explain why you are changing this score..."
                  rows={3}
                  className={cn(
                    'w-full px-3 py-2 rounded border bg-background text-sm focus:outline-none focus:ring-2 focus:ring-ring resize-none',
                    reasonError ? 'border-destructive' : 'border-input'
                  )}
                  autoFocus
                />
                {reasonError && (
                  <p className="text-xs text-destructive mt-1">{reasonError}</p>
                )}
              </div>
              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={handleReasonCancel}>
                  Cancel
                </Button>
                <Button onClick={handleReasonConfirm}>
                  Confirm Override
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* "Next" button for wizard navigation */}
      <div className="text-sm text-muted-foreground text-center">
        {overrides.length > 0
          ? `${overrides.length} override(s) applied — aggregate recalculated`
          : 'Click any score to review and override'}
      </div>
    </div>
  )
}

