  title: string
  description: string
  component: ReactNode
}

interface StepWizardProps {
  steps: Step[]
  currentStep: number
  onNext: () => void
  onBack: () => void
  canGoNext: boolean
  canGoBack: boolean
  nextLabel?: string
  backLabel?: string
  containerClassName?: string
