export default function StepWizard({
  steps,
  currentStep,
  onNext,
  onBack,
  canGoNext,
  canGoBack,
  nextLabel = 'Next',
  backLabel = 'Back',
  containerClassName,
}: StepWizardProps) {
  return (
    <div className={cn('max-w-3xl mx-auto px-4', containerClassName)}>
      {/* Step indicator bar */}
      <div className="mb-8 overflow-x-auto scrollbar-hide">
        <div className="flex items-center justify-start md:justify-center min-w-max px-2">
          {steps.map((step, index) => {
            const lineWidth = steps.length > 4 ? 'w-6 md:w-12' : 'w-16 md:w-24'
            const isDone = index < currentStep
            const isActive = index === currentStep
            return (
            <div key={step.id} className="flex items-center">
              <div className="flex flex-col items-center gap-1.5">
                <div
                  className={cn(
                    'flex items-center justify-center w-9 h-9 md:w-11 md:h-11 rounded-full text-xs md:text-sm font-bold transition-all duration-300 shadow-sm',
                    isDone && 'bg-primary text-primary-foreground shadow-primary/25',
                    isActive && 'bg-primary text-primary-foreground ring-4 ring-primary/20 shadow-primary/30 scale-110',
                    !isDone && !isActive && 'bg-muted text-muted-foreground border-2 border-muted-foreground/20'
                  )}
                >
                  {isDone ? <Check size={16} strokeWidth={3} /> : index + 1}
                </div>
                <div className="text-center">
                  <p className={cn(
                    'text-xs md:text-sm font-semibold tracking-tight',
                    isActive ? 'text-foreground' : isDone ? 'text-foreground/80' : 'text-muted-foreground/50'
                  )}>
                    {step.title}
                  </p>
                  <p className={cn(
                    'text-[11px] leading-tight hidden md:block',
                    isActive ? 'text-muted-foreground/80' : isDone ? 'text-muted-foreground/60' : 'text-muted-foreground/30'
                  )}>
                    {step.description}
                  </p>
                </div>
              </div>

              {index < steps.length - 1 && (
                <div className={cn(
                  lineWidth, 'h-0.5 mx-1.5 md:mx-3 rounded-full transition-colors duration-300',
                  isDone ? 'bg-primary' : 'bg-muted-foreground/15'
                )} />
              )}
            </div>
            )
          })}
        </div>
      </div>

      {/* Step content */}
      <Card className="shadow-md border-border/60">
        <CardContent key={currentStep} className="p-6 md:p-8 animate-fade-in">
          {steps[currentStep]?.component}
        </CardContent>
      </Card>

      {/* Navigation */}
      <div className="flex justify-between mt-6">
        <Button
          variant="outline"
          onClick={onBack}
          disabled={!canGoBack}
        >
          {backLabel}
        </Button>
        <Button
          onClick={onNext}
          disabled={!canGoNext}
          className={cn(
            'transition-all',
            canGoNext && 'shadow-sm'
          )}
        >
          {currentStep === steps.length - 1 ? 'Finish' : nextLabel}
        </Button>
      </div>
    </div>
  )
}

