import { useState, useRef, DragEvent, ChangeEvent } from 'react'
import { Upload, FileText, X, CheckCircle2, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'

interface UploadZoneProps {
  onFilesSelected: (files: File[]) => void
  onRemove?: () => void
  maxSizeMB?: number
  disabled?: boolean
  multiple?: boolean
}

const ACCEPTED_EXTENSION = '.ipynb'

export default function UploadZone({ onFilesSelected, maxSizeMB = 20, disabled = false, multiple = false }: UploadZoneProps) {
  const [files, setFiles] = useState<File[]>([])
  const [error, setError] = useState<string | null>(null)
  const [dragOver, setDragOver] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const maxSizeBytes = maxSizeMB * 1024 * 1024

  const validateFile = (f: File): string | null => {
    const ext = '.' + f.name.split('.').pop()?.toLowerCase()
    if (ext !== ACCEPTED_EXTENSION) {
      return `Invalid file type. Only .ipynb files are accepted.`
    }
    if (f.size > maxSizeBytes) {
      return `File too large. Maximum size is ${maxSizeMB}MB.`
    }
    if (f.size === 0) {
      return 'File is empty.'
    }
    return null
  }

  const handleFiles = (newFiles: FileList) => {
    setError(null)
    const validFiles: File[] = []

    for (let i = 0; i < newFiles.length; i++) {
      const f = newFiles[i]
      const validationError = validateFile(f)
      if (validationError) {
        setError(validationError)
        return
      }
      validFiles.push(f)
    }

    if (validFiles.length === 0) return
    setFiles(validFiles)
    onFilesSelected(validFiles)
  }

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()
    if (!disabled) setDragOver(true)
  }

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()
    setDragOver(false)
  }

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()
    setDragOver(false)
    if (disabled) return
    const droppedFiles = e.dataTransfer.files
    if (droppedFiles.length > 0) handleFiles(droppedFiles)
  }

  const handleClick = () => {
    if (!disabled) inputRef.current?.click()
  }

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files
    if (selectedFiles && selectedFiles.length > 0) handleFiles(selectedFiles)
    e.target.value = ''
  }

  const clearFiles = () => {
    setFiles([])
    setError(null)
    onRemove?.()
  }

  const formatSize = (bytes: number): string => {
    if (bytes < 1024) return bytes + ' B'
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB'
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB'
  }

  return (
    <div className="w-full max-w-xl mx-auto">
      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={handleClick}
        className={cn(
          'relative flex flex-col items-center justify-center rounded-lg border-2 border-dashed p-10 transition-all cursor-pointer',
          dragOver && !disabled
            ? 'border-primary bg-primary/5 scale-[1.02]'
            : 'border-muted-foreground/30 hover:border-muted-foreground/50',
          disabled && 'opacity-50 cursor-not-allowed',
          files.length > 0 && !error && 'border-green-500/50 bg-green-50/50 dark:bg-green-950/20'
        )}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label={multiple ? 'Upload Jupyter Notebooks' : 'Upload Jupyter Notebook'}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') handleClick() }}
      >
        <input
          ref={inputRef}
          type="file"
          accept={ACCEPTED_EXTENSION}
          onChange={handleInputChange}
          className="hidden"
          disabled={disabled}
          multiple={multiple}
          aria-hidden="true"
        />

        {files.length === 0 && !error && (
          <>
            <div className="mb-4 rounded-full bg-primary/10 p-3">
              <Upload size={32} className="text-primary" />
            </div>
            <h3 className="text-lg font-semibold text-foreground mb-1">
              Upload Jupyter Notebook{multiple ? 's' : ''}
            </h3>
            <p className="text-sm text-muted-foreground text-center">
              Drag & drop your .ipynb file{multiple ? 's' : ''} here, or click to browse
            </p>
            <p className="text-xs text-muted-foreground mt-2">
              .ipynb files up to {maxSizeMB}MB
            </p>
          </>
        )}

        {files.length > 0 && !error && (
          <div className="flex flex-col items-center gap-2">
            <CheckCircle2 size={32} className="text-green-500" />
            <p className="font-medium text-foreground">
              {files.length} file{files.length !== 1 ? 's' : ''} selected
            </p>
            <p className="text-xs text-muted-foreground text-center max-w-sm truncate">
              {files.map(f => f.name).join(', ')}
            </p>
            {multiple && files.length > 1 && (
              <p className="text-xs text-green-600 dark:text-green-400">
                Click &quot;Upload All&quot; to begin batch upload
              </p>
            )}
            <button
              onClick={(e) => { e.stopPropagation(); clearFiles() }}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground mt-1"
              type="button"
            >
              <X size={14} />
              Remove all
            </button>
          </div>
        )}

        {error && (
          <div className="flex flex-col items-center gap-2">
            <AlertCircle size={32} className="text-destructive" />
            <p className="text-sm font-medium text-destructive text-center">{error}</p>
            <button
              onClick={(e) => { e.stopPropagation(); clearFiles() }}
              className="text-xs text-muted-foreground hover:text-foreground underline"
              type="button"
            >
              Try again
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

