import { useState, useCallback, useRef, useEffect } from 'react'
import { useBatchStore } from '@/stores/batchStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError, QueueFileEntry, BatchStatusResponse } from '@/types/api'

const POLL_INTERVAL_MS = 3000

interface UseBatchReturn {
  uploadBatchFiles: (files: File[]) => Promise<void>
  removeFile: (id: string) => void
  clearQueue: () => void

  startEvaluation: () => Promise<void>
  isEvaluating: boolean
  evaluationStatus: BatchStatusResponse | null

  queueFiles: QueueFileEntry[]
  batchSessionId: string | null
  isUploading: boolean
  uploadError: ApiError | null
}

export function useBatch(): UseBatchReturn {
  const {
    queueFiles,
    batchSessionId,
    isUploading,
    isEvaluating,
    evaluationStatus,
    addToQueue,
    removeFromQueue,
    updateFileStatus,
    setQueueFiles,
    setBatchSessionId,
    setIsUploading,
    setIsEvaluating,
    setEvaluationStatus,
  } = useBatchStore()

  const [uploadError, setUploadError] = useState<ApiError | null>(null)
  const pollingRef = useRef<ReturnType<typeof setInterval> | null>(null)

  useEffect(() => {
    if (!evaluationStatus) return
    const terminal = ['completed', 'failed', 'completed_with_errors']
    if (terminal.includes(evaluationStatus.overall_status)) {
      if (pollingRef.current) {
        clearInterval(pollingRef.current)
        pollingRef.current = null
      }
      setIsEvaluating(false)
    }
  }, [evaluationStatus, setIsEvaluating])

  useEffect(() => {
    return () => {
      if (pollingRef.current) clearInterval(pollingRef.current)
    }
  }, [])

  const uploadBatchFiles = useCallback(async (files: File[]) => {
    setUploadError(null)
    setIsUploading(true)

    const entries: QueueFileEntry[] = files.map((f) => ({
      file: f,
      id: crypto.randomUUID(),
      status: 'pending' as const,
    }))
    addToQueue(entries)

    try {
      for (const entry of entries) {
        updateFileStatus(entry.id, { status: 'uploading' })
      }

      const currentSessionId = batchSessionId || undefined
      const response = await apiClient.uploadBatch(files, currentSessionId)

      if (!batchSessionId) {
        setBatchSessionId(response.session_id)
      }

      const serverMap = new Map(
        response.notebooks.map((n) => [n.filename, n])
      )

      for (const entry of entries) {
        const serverResult = serverMap.get(entry.file.name)
        if (serverResult?.status === 'uploaded') {
          updateFileStatus(entry.id, { status: 'validated', cells: serverResult.cells })
        } else {
          updateFileStatus(entry.id, {
            status: 'failed',
            error: serverResult?.error || 'Upload failed',
          })
        }
      }
    } catch (err) {
      for (const entry of entries) {
        updateFileStatus(entry.id, {
          status: 'failed',
          error: err instanceof ApiClientError
            ? err.apiError.message
            : 'Network error during upload',
        })
      }
      if (err instanceof ApiClientError) {
        setUploadError(err.apiError)
      } else {
        setUploadError({
          error: 'network_error',
          message: err instanceof Error ? err.message : 'Failed to upload files',
          details: [],
        })
      }
    } finally {
      setIsUploading(false)
    }
  }, [batchSessionId, addToQueue, updateFileStatus, setBatchSessionId, setIsUploading])

  const removeFile = useCallback((id: string) => {
    removeFromQueue(id)
  }, [removeFromQueue])

  const clearQueue = useCallback(() => {
    setQueueFiles([])
  }, [setQueueFiles])

  const startEvaluation = useCallback(async () => {
    const sessionId = useBatchStore.getState().batchSessionId
    if (!sessionId || isEvaluating) return

    setUploadError(null)
    setIsEvaluating(true)

    try {
      await apiClient.triggerBatchEvaluation(sessionId)
      const poll = async () => {
        try {
          const status = await apiClient.getBatchStatus(sessionId)
          setEvaluationStatus(status)
        } catch {
          // Polling errors are non-fatal — retry on next interval
        }
      }
      await poll()
      pollingRef.current = setInterval(poll, POLL_INTERVAL_MS)
    } catch (err) {
      setIsEvaluating(false)
      if (err instanceof ApiClientError) {
        setUploadError(err.apiError)
      } else {
        setUploadError({
          error: 'evaluation_error',
          message: err instanceof Error ? err.message : 'Failed to start evaluation',
          details: [],
        })
      }
    }
  }, [isEvaluating, setIsEvaluating, setEvaluationStatus])

  return {
    uploadBatchFiles,
    removeFile,
    clearQueue,
    startEvaluation,
    isEvaluating,
    evaluationStatus,
    queueFiles,
    batchSessionId,
    isUploading,
    uploadError,
  }
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { apiClient } from '@/services/api'
import { useBatchStore } from '@/stores/batchStore'
import type { CohortSummaryResponse } from '@/types/api'

interface UseCohortReturn {
  cohortData: CohortSummaryResponse | null
  isLoading: boolean
  error: string | null
  refresh: () => Promise<void>
}

export function useCohort(): UseCohortReturn {
  const [cohortData, setCohortData] = useState<CohortSummaryResponse | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const hasFetchedRef = useRef(false)

  const fetchCohort = useCallback(async () => {
    const sessionId = useBatchStore.getState().batchSessionId
    if (!sessionId) return

    setIsLoading(true)
    setError(null)

    try {
      const data = await apiClient.getCohortSummary(sessionId)
      setCohortData(data)
      hasFetchedRef.current = true
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load cohort summary')
    } finally {
      setIsLoading(false)
    }
  }, [])

  // Fetch once when session becomes available and evaluation is complete
  const evaluationStatus = useBatchStore((s) => s.evaluationStatus)
  const comparisonData = useBatchStore((s) => s.comparisonData)

  useEffect(() => {
    if (!hasFetchedRef.current && comparisonData && evaluationStatus) {
      const isComplete = ['completed', 'failed', 'completed_with_errors'].includes(
        evaluationStatus.overall_status
      )
      if (isComplete) {
        fetchCohort()
      }
    }
  }, [comparisonData, evaluationStatus, fetchCohort])

  return {
    cohortData,
    isLoading,
    error,
    refresh: fetchCohort,
  }
}

import { useCallback } from 'react'
import { useBatchStore } from '@/stores/batchStore'
import { apiClient } from '@/services/api'
import type { ComparisonResponse } from '@/types/api'

interface UseComparisonDataReturn {
  comparisonData: ComparisonResponse | null
  isLoadingComparison: boolean
  selectedStudent: string | null
  selectStudent: (filename: string | null) => void
  fetchComparison: () => Promise<void>
  refreshComparison: () => Promise<void>
  reevaluateNotebook: (filename: string) => Promise<void>
  recalculateNotebook: (filename: string) => Promise<void>
  updateRowScore: (filename: string, criterionName: string, newScore: number) => void
}

export function useComparisonData(): UseComparisonDataReturn {
  const {
    comparisonData,
    isLoadingComparison,
    selectedStudent,
    setComparisonData,
    setIsLoadingComparison,
    setSelectedStudent,
    setReevaluating,
    updateComparisonRow,
  } = useBatchStore()

  const fetchComparison = useCallback(async () => {
    const sessionId = useBatchStore.getState().batchSessionId
    if (!sessionId) return

    setIsLoadingComparison(true)
    try {
      const data = await apiClient.getComparison(sessionId)
      setComparisonData(data)
    } catch (err) {
      // Non-fatal — retry on next poll
      console.error('Failed to fetch comparison data:', err)
    } finally {
      setIsLoadingComparison(false)
    }
  }, [setComparisonData, setIsLoadingComparison])

  const refreshComparison = useCallback(async () => {
    await fetchComparison()
  }, [fetchComparison])

  const selectStudent = useCallback((filename: string | null) => {
    setSelectedStudent(filename)
  }, [setSelectedStudent])

  const reevaluateNotebook = useCallback(async (filename: string) => {
    const sessionId = useBatchStore.getState().batchSessionId
    if (!sessionId) return

    setReevaluating(filename, true)
    try {
      const result = await apiClient.reevaluateNotebook(sessionId, filename)
      // Update the row with new aggregate scores from the backend response
      if (result.aggregate_score !== undefined) {
        updateComparisonRow(filename, {
          aggregate_score: result.aggregate_score,
          aggregate_percentage: result.aggregate_percentage || 0,
        })
      }
    } catch (err) {
      console.error(`Re-evaluate failed for ${filename}:`, err)
      // Re-throw so callers (BatchSideDrawer) can catch and show error feedback
      throw err
    } finally {
      setReevaluating(filename, false)
    }
  }, [updateComparisonRow, setReevaluating])

  const recalculateNotebook = useCallback(async (filename: string) => {
    const sessionId = useBatchStore.getState().batchSessionId
    if (!sessionId) return

    setReevaluating(filename, true)
    try {
      const result = await apiClient.recalculateNotebook(sessionId, filename)
      // Update the row with new aggregate scores
      if (result.aggregate_score !== undefined) {
        updateComparisonRow(filename, {
          aggregate_score: result.aggregate_score,
          aggregate_percentage: result.aggregate_percentage || 0,
        })
      }
    } catch (err) {
      console.error(`Recalculate failed for ${filename}:`, err)
    } finally {
      setReevaluating(filename, false)
    }
  }, [updateComparisonRow, setReevaluating])

  const updateRowScore = useCallback((filename: string, criterionName: string, newScore: number) => {
    const state = useBatchStore.getState()
    const data = state.comparisonData
    if (!data) return

    const updatedRows = data.rows.map((row) => {
      if (row.filename !== filename) return row
      const updatedScores = row.per_criterion_scores.map((cs) =>
        cs.criterion_name === criterionName ? { ...cs, score: newScore } : cs
      )
      // Recalculate aggregate based on new scores
      let weightedSum = 0
      let totalWeight = 0
      for (const cs of updatedScores) {
        weightedSum += (cs.score / 5) * cs.weight
        totalWeight += cs.weight
      }
      const newAggregateScore = totalWeight > 0
        ? Math.round((weightedSum / totalWeight) * 5 * 100) / 100
        : 0
      const newAggregatePct = Math.round((newAggregateScore / 5) * 100 * 10) / 10

      return {
        ...row,
        per_criterion_scores: updatedScores,
        aggregate_score: newAggregateScore,
        aggregate_percentage: newAggregatePct,
      }
    })

    setComparisonData({ ...data, rows: updatedRows })
  }, [setComparisonData])

  return {
    comparisonData,
    isLoadingComparison,
    selectedStudent,
    selectStudent,
    fetchComparison,
    refreshComparison,
    reevaluateNotebook,
    recalculateNotebook,
    updateRowScore,
  }
}

import { useState, useCallback } from 'react'
import { useSessionStore } from '@/stores/sessionStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError, EvaluationResult } from '@/types/api'

interface UseEvaluationReturn {
  startEvaluation: (sessionId: string) => Promise<void>
  getEvaluation: (sessionId: string) => Promise<void>
  isEvaluating: boolean
  progress: { step: string; status: string } | null
  error: ApiError | null
  result: EvaluationResult | null
}

export function useEvaluation(): UseEvaluationReturn {
  const {
    setEvaluationResult,
    setEvaluating: setStoreEvaluating,
    setEvaluationProgress,
    setError: setStoreError,
  } = useSessionStore()

  const [isEvaluating, setIsEvaluating] = useState(false)
  const [progress, setLocalProgress] = useState<{ step: string; status: string } | null>(null)
  const [error, setLocalError] = useState<ApiError | null>(null)
  const [result, setLocalResult] = useState<EvaluationResult | null>(null)

  const startEvaluation = useCallback(async (sessionId: string) => {
    setIsEvaluating(true)
    setStoreEvaluating(true)
    setLocalError(null)
    setStoreError(null)
    setLocalProgress(null)
    setLocalResult(null)
    setEvaluationResult(null)

    try {
      await apiClient.evaluateNotebookStream(
        sessionId,
        // onStep
        (step: string, status: string) => {
          const progressData = { step, status }
          setLocalProgress(progressData)
          setEvaluationProgress(progressData)
        },
        // onCriterion
        (_criterion: string, _score: number) => {
          // Could update partial results per criterion if needed
        },
        // onResult
        (evalResult: EvaluationResult) => {
          setLocalResult(evalResult)
          setEvaluationResult(evalResult)
        },
        // onError
        (streamError: ApiClientError) => {
          setLocalError(streamError.apiError)
          setStoreError(streamError.apiError)
        }
      )
    } catch (err) {
      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'evaluation_error',
          message: err instanceof Error ? err.message : 'Failed to evaluate notebook',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    } finally {
      setIsEvaluating(false)
      setStoreEvaluating(false)
    }
  }, [setEvaluationResult, setStoreEvaluating, setEvaluationProgress, setStoreError])

  const getEvaluation = useCallback(async (sessionId: string) => {
    setIsEvaluating(true)
    setStoreEvaluating(true)
    setLocalError(null)
    setStoreError(null)

    try {
      const evalResult = await apiClient.evaluateNotebook(sessionId)
      setLocalResult(evalResult)
      setEvaluationResult(evalResult)
    } catch (err) {
      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'evaluation_error',
          message: err instanceof Error ? err.message : 'Failed to evaluate notebook',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    } finally {
      setIsEvaluating(false)
      setStoreEvaluating(false)
    }
  }, [setEvaluationResult, setStoreEvaluating, setStoreError])

  return {
    startEvaluation,
    getEvaluation,
    isEvaluating,
    progress,
    error,
    result,
  }
}

import { useState, useCallback, useRef, useEffect } from 'react'
import { useSessionStore } from '@/stores/sessionStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError, ReportRequest, ReportStatusResponse } from '@/types/api'

interface UseReportReturn {
  triggerReport: (sessionId: string, request: ReportRequest) => Promise<void>
  getReportUrl: (sessionId: string) => string
  downloadReport: (sessionId: string) => void
  isGenerating: boolean
  status: ReportStatusResponse | null
  error: ApiError | null
  downloadUrl: string | null
}

export function useReport(): UseReportReturn {
  const {
    setReportStatus,
    setReportRequest,
    setError: setStoreError,
  } = useSessionStore()

  const [isGenerating, setIsGenerating] = useState(false)
  const [status, setLocalStatus] = useState<ReportStatusResponse | null>(null)
  const [error, setLocalError] = useState<ApiError | null>(null)
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null)
  const pollingRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // Cleanup polling on unmount
  useEffect(() => {
    return () => {
      if (pollingRef.current) {
        clearInterval(pollingRef.current)
        pollingRef.current = null
      }
    }
  }, [])

  const triggerReport = useCallback(async (sessionId: string, request: ReportRequest) => {
    setIsGenerating(true)
    setLocalError(null)
    setStoreError(null)
    setLocalStatus(null)
    setDownloadUrl(null)
    setReportRequest(request)

    try {
      // Trigger report generation
      const response = await apiClient.generateReport(sessionId, request)
      setLocalStatus({ report_id: response.report_id, status: 'generating', mode: request.mode })
      setReportStatus({ report_id: response.report_id, status: 'generating', mode: request.mode })

      // Poll for status
      const maxPolls = 15 // 30 seconds total (2s interval)
      let pollCount = 0

      await new Promise<void>((resolve, reject) => {
        pollingRef.current = setInterval(async () => {
          pollCount++
          try {
            const reportStatus = await apiClient.getReportStatus(sessionId)
            setLocalStatus(reportStatus)
            setReportStatus(reportStatus)

            if (reportStatus.status === 'completed') {
              if (pollingRef.current) {
                clearInterval(pollingRef.current)
                pollingRef.current = null
              }
              setDownloadUrl(apiClient.downloadReportUrl(sessionId))
              resolve()
            } else if (reportStatus.status === 'failed') {
              if (pollingRef.current) {
                clearInterval(pollingRef.current)
                pollingRef.current = null
              }
              reject(new Error('Report generation failed'))
            } else if (pollCount >= maxPolls) {
              if (pollingRef.current) {
                clearInterval(pollingRef.current)
                pollingRef.current = null
              }
              reject(new Error('Report generation timed out'))
            }
          } catch (pollErr) {
            if (pollingRef.current) {
              clearInterval(pollingRef.current)
              pollingRef.current = null
            }
            reject(pollErr)
          }
        }, 2000)
      })
    } catch (err) {
      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'report_error',
          message: err instanceof Error ? err.message : 'Failed to generate report',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    } finally {
      setIsGenerating(false)
    }
  }, [setReportStatus, setReportRequest, setStoreError])

  const getReportUrl = useCallback((sessionId: string): string => {
    return apiClient.downloadReportUrl(sessionId)
  }, [])

  const downloadReport = useCallback((sessionId: string) => {
    const url = apiClient.downloadReportUrl(sessionId)
    const link = document.createElement('a')
    link.href = url
    link.download = ''  // Let the server set the filename
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }, [])

  return {
    triggerReport,
    getReportUrl,
    downloadReport,
    isGenerating,
    status,
    error,
    downloadUrl,
  }
}

import { useState, useCallback } from 'react'
import { useSessionStore } from '@/stores/sessionStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError, RubricTemplateSummary, RubricTemplate, Criterion } from '@/types/api'

interface UseRubricReturn {
  templates: RubricTemplateSummary[] | null
  selectedTemplate: RubricTemplate | null
  isLoading: boolean
  error: ApiError | null
  customCriteria: Criterion[]
  loadTemplates: () => Promise<void>
  selectTemplate: (name: string) => void
  addCustomCriterion: (criterion: Criterion) => void
  removeCustomCriterion: (index: number) => void
  saveRubric: () => Promise<void>
  setCustomCriteria: (criteria: Criterion[]) => void
  setSelectedTemplate: (template: RubricTemplate | null) => void
}

export function useRubric(): UseRubricReturn {
  const {
    rubricTemplates,
    setRubricTemplates,
    selectedRubric,
    setSelectedRubric,
    setError: setStoreError,
  } = useSessionStore()

  const [templates, setTemplates] = useState<RubricTemplateSummary[] | null>(rubricTemplates)
  const [selectedTemplate, setSelectedTemplate] = useState<RubricTemplate | null>(selectedRubric)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setLocalError] = useState<ApiError | null>(null)
  const [customCriteria, setCustomCriteria] = useState<Criterion[]>([])

  const loadTemplates = useCallback(async () => {
    setIsLoading(true)
    setLocalError(null)
    setStoreError(null)

    try {
      const response = await apiClient.getRubricTemplates()
      setTemplates(response.templates)
      setRubricTemplates(response.templates)
    } catch (err) {
      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'network_error',
          message: err instanceof Error ? err.message : 'Failed to load rubric templates',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    } finally {
      setIsLoading(false)
    }
  }, [setRubricTemplates, setStoreError])

  const selectTemplate = useCallback((name: string) => {
    if (!templates) return
    const summary = templates.find((t) => t.name === name)
    if (!summary) return

    // Create a placeholder template — full criteria will be loaded when needed
    setSelectedTemplate({
      name: summary.name,
      criteria: [],
    })
  }, [templates])

  const addCustomCriterion = useCallback((criterion: Criterion) => {
    setCustomCriteria((prev) => [...prev, criterion])
  }, [])

  const removeCustomCriterion = useCallback((index: number) => {
    setCustomCriteria((prev) => prev.filter((_, i) => i !== index))
  }, [])

  const saveRubric = useCallback(async () => {
    if (!selectedTemplate) return

    // Normalize weights to sum to 100%
    const allCriteria = [...selectedTemplate.criteria, ...customCriteria]
    const totalWeight = allCriteria.reduce((sum, c) => sum + c.weight, 0)

    let normalizedCriteria: Criterion[]
    if (totalWeight > 0 && totalWeight !== 100) {
      const factor = 100 / totalWeight
      normalizedCriteria = allCriteria.map((c) => ({
        ...c,
        weight: Math.round(c.weight * factor),
      }))
    } else {
      normalizedCriteria = allCriteria
    }

    const rubricToSave: RubricTemplate = {
      name: selectedTemplate.name,
      criteria: normalizedCriteria,
    }

    setIsLoading(true)
    setLocalError(null)
    setStoreError(null)

    try {
      const sessionId = useSessionStore.getState().sessionId
      if (!sessionId) {
        throw new Error('No active session')
      }

      await apiClient.saveRubric(rubricToSave, sessionId)
      setSelectedRubric(rubricToSave)
      setSelectedTemplate(rubricToSave)
    } catch (err) {
      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'save_error',
          message: err instanceof Error ? err.message : 'Failed to save rubric',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    } finally {
      setIsLoading(false)
    }
  }, [selectedTemplate, customCriteria, setSelectedRubric, setStoreError])

  return {
    templates,
    selectedTemplate,
    isLoading,
    error,
    customCriteria,
    loadTemplates,
    selectTemplate,
    addCustomCriterion,
    removeCustomCriterion,
    saveRubric,
    setCustomCriteria,
    setSelectedTemplate,
  }
}

import { useState, useCallback, useRef } from 'react'
import { useSessionStore } from '@/stores/sessionStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError, UnderstandingResult } from '@/types/api'

interface UseUnderstandingReturn {
  analyze: () => Promise<void>
  isAnalyzing: boolean
  streamingText: string
  error: ApiError | null
  clearError: () => void
}

export function useUnderstanding(): UseUnderstandingReturn {
  const {
    sessionId,
    setUnderstandingResult,
    setAnalyzing: setStoreAnalyzing,
    setError: setStoreError,
  } = useSessionStore()
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [streamingText, setStreamingText] = useState('')
  const [error, setLocalError] = useState<ApiError | null>(null)
  const chunkBufferRef = useRef<string[]>([])

  const clearError = useCallback(() => {
    setLocalError(null)
    setStoreError(null)
  }, [setStoreError])

  const analyze = useCallback(async () => {
    if (!sessionId) {
      const err: ApiError = {
        error: 'session_error',
        message: 'No active session. Please upload a notebook first.',
        details: [],
      }
      setLocalError(err)
      setStoreError(err)
      return
    }

    setIsAnalyzing(true)
    setStoreAnalyzing(true)
    setLocalError(null)
    setStoreError(null)
    setStreamingText('')
    chunkBufferRef.current = []

    // Always get structured data from non-streaming endpoint first
    try {
      const response = await apiClient.getUnderstanding(sessionId)
      const result = response.understanding

      // Then try streaming for progressive reveal
      try {
        await new Promise<void>((resolve, reject) => {
          let hasReceivedData = false
          const timeoutId = setTimeout(() => {
            if (!hasReceivedData) {
              reject(new Error('Stream timeout'))
            }
          }, 3000)

          apiClient.getUnderstandingStream(
            sessionId,
            (text: string) => {
              hasReceivedData = true
              clearTimeout(timeoutId)
              chunkBufferRef.current.push(text)
              setStreamingText(chunkBufferRef.current.join(''))
            },
            () => {
              clearTimeout(timeoutId)
              const fullText = chunkBufferRef.current.join('')
              // Try to parse streaming text as JSON for structured result
              try {
                const parsed = JSON.parse(fullText)
                const parsedResult: UnderstandingResult = {
                  purpose: parsed.purpose || result.purpose,
                  key_libraries: parsed.key_libraries || result.key_libraries,
                  techniques: parsed.techniques || result.techniques,
                  summary: parsed.summary || result.summary,
                  overall_quality: parsed.overall_quality || result.overall_quality,
                }
                setUnderstandingResult(parsedResult)
              } catch {
                // Fall back to the non-streaming result
                setUnderstandingResult(result)
              }
              setIsAnalyzing(false)
              setStoreAnalyzing(false)
              resolve()
            },
            (streamError: ApiClientError) => {
              clearTimeout(timeoutId)
              reject(streamError)
            }
          )
        })
      } catch {
        // Streaming failed or timed out — use structured result with typewriter effect
        const summaryText = result.summary || result.purpose || ''
        const words = summaryText.split(' ')
        chunkBufferRef.current = []

        for (let i = 0; i < words.length; i++) {
          chunkBufferRef.current.push(words[i])
          setStreamingText(chunkBufferRef.current.join(' '))
          await new Promise((r) => setTimeout(r, 30))
        }

        setUnderstandingResult(result)
        setIsAnalyzing(false)
        setStoreAnalyzing(false)
      }
    } catch (err) {
      setIsAnalyzing(false)
      setStoreAnalyzing(false)

      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'analysis_error',
          message:
            err instanceof Error
              ? err.message
              : 'Failed to analyze notebook',
          details: [],
        }
      }
      setLocalError(apiError)
      setStoreError(apiError)
    }
  }, [sessionId, setUnderstandingResult, setStoreAnalyzing, setStoreError])

  return {
    analyze,
    isAnalyzing,
    streamingText,
    error,
    clearError,
  }
}

import { useState, useCallback } from 'react'
import { useSessionStore } from '@/stores/sessionStore'
import { apiClient, ApiClientError } from '@/services/api'
import type { ApiError } from '@/types/api'

export type UploadStage = 'idle' | 'uploading' | 'validating' | 'parsing' | 'ready'

interface UseUploadReturn {
  uploadFile: (file: File) => Promise<void>
  isUploading: boolean
  uploadStage: UploadStage
  progress: number
  error: ApiError | null
}

export function useUpload(): UseUploadReturn {
  const { sessionId, setSessionId, setUploadedFile, setError } = useSessionStore()
  const [isUploading, setIsUploading] = useState(false)
  const [uploadStage, setUploadStage] = useState<UploadStage>('idle')
  const [progress, setProgress] = useState(0)
  const [error, setLocalError] = useState<ApiError | null>(null)

  const uploadFile = useCallback(async (file: File) => {
    // Client-side validation
    const ext = '.' + file.name.split('.').pop()?.toLowerCase()
    if (ext !== '.ipynb') {
      const err: ApiError = {
        error: 'invalid_format',
        message: 'Invalid file type. Only .ipynb files are accepted.',
        details: [`Expected .ipynb extension, got ${ext}`],
      }
      setLocalError(err)
      setError(err)
      return
    }

    const maxSizeBytes = 20 * 1024 * 1024
    if (file.size > maxSizeBytes) {
      const err: ApiError = {
        error: 'file_too_large',
        message: 'File too large. Maximum size is 20MB.',
        details: [`File size: ${(file.size / (1024 * 1024)).toFixed(1)}MB`],
      }
      setLocalError(err)
      setError(err)
      return
    }

    if (file.size === 0) {
      const err: ApiError = {
        error: 'invalid_format',
        message: 'File is empty.',
        details: ['Uploaded file has zero bytes'],
      }
      setLocalError(err)
      setError(err)
      return
    }

    // Generate session ID if not set
    let currentSessionId = sessionId
    if (!currentSessionId) {
      currentSessionId = crypto.randomUUID()
      setSessionId(currentSessionId)
    }

    setIsUploading(true)
    setLocalError(null)
    setError(null)
    setUploadStage('uploading')
    setProgress(10)

    try {
      setUploadStage('validating')
      setProgress(40)

      const response = await apiClient.uploadFile(file, currentSessionId)

      setUploadStage('parsing')
      setProgress(70)

      // Store parsed notebook in session
      setUploadedFile(file, response.notebook)

      setUploadStage('ready')
      setProgress(100)
      setIsUploading(false)
    } catch (err) {
      setIsUploading(false)
      setUploadStage('idle')
      setProgress(0)

      let apiError: ApiError
      if (err instanceof ApiClientError) {
        apiError = err.apiError
      } else {
        apiError = {
          error: 'network_error',
          message: err instanceof Error ? err.message : 'Failed to upload file',
          details: [],
        }
      }
      setLocalError(apiError)
      setError(apiError)
    }
  }, [sessionId, setSessionId, setUploadedFile, setError])

  return {
    uploadFile,
    isUploading,
    uploadStage,
    progress,
    error,
  }
}

import { useState, useCallback } from 'react'
import { apiClient, ApiClientError } from '@/services/api'
import { useSessionStore } from '@/stores/sessionStore'
import type { VivaReportRequest } from '@/types/api'

export function useVivaReport() {
  const {
    sessionId,
    analysisResult,
    setAnalysisResult,
    setVivaAnalyzing,
    setAnalysisError: setStoreAnalysisError,
    vivaReportStatus,
    setVivaReportStatus,
    setVivaReportRequest,
    studentName,
    assignmentName,
    courseName,
    setStudentName,
    setAssignmentName,
    setCourseName,
  } = useSessionStore()

  // Local state for loading/error during async operations
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [isGeneratingVivaReport, setIsGeneratingVivaReport] = useState(false)
  const [vivaReportError, setVivaReportError] = useState<string | null>(null)
  const [vivaPdfUrl, setVivaPdfUrl] = useState<string | null>(null)
  const [vivaPreviewHtml, setVivaPreviewHtml] = useState<string | null>(null)

  const triggerAnalysis = useCallback(async () => {
    if (!sessionId) return
    setIsAnalyzing(true)
    setVivaReportError(null)
    setAnalysisResult(null)
    setVivaAnalyzing(true)

    try {
      const result = await apiClient.triggerAnalysis(sessionId)
      setAnalysisResult(result.analysis)
    } catch (err) {
      const msg = err instanceof ApiClientError ? err.apiError.message : 'Analysis failed'
      setVivaReportError(msg)
      setStoreAnalysisError(msg)
    } finally {
      setIsAnalyzing(false)
      setVivaAnalyzing(false)
    }
  }, [sessionId, setAnalysisResult, setVivaAnalyzing, setStoreAnalysisError])

  const generateVivaReport = useCallback(async () => {
    if (!sessionId || !analysisResult) return
    setIsGeneratingVivaReport(true)
    setVivaReportError(null)

    const request: VivaReportRequest = {
      student_name: studentName,
      assignment_name: assignmentName,
      course_name: courseName,
    }
    setVivaReportRequest(request)

    try {
      const response = await apiClient.triggerVivaReport(sessionId, request)
      setVivaReportStatus({
        report_id: response.report_id,
        status: 'completed',
      })

      // Set download URL
      const url = apiClient.downloadVivaReportUrl(sessionId)
      setVivaPdfUrl(url)
    } catch (err) {
      const msg = err instanceof ApiClientError ? err.apiError.message : 'Report generation failed'
      setVivaReportError(msg)
    } finally {
      setIsGeneratingVivaReport(false)
    }
  }, [sessionId, analysisResult, studentName, assignmentName, courseName, setVivaReportRequest, setVivaReportStatus])

  const downloadVivaPdf = useCallback(() => {
    if (vivaPdfUrl) {
      window.open(vivaPdfUrl, '_blank')
    }
  }, [vivaPdfUrl])

  const resetViva = useCallback(() => {
    setAnalysisResult(null)
    setVivaReportStatus(null)
    setVivaPdfUrl(null)
    setVivaPreviewHtml(null)
    setVivaReportError(null)
  }, [setAnalysisResult, setVivaReportStatus])

  return {
    // State
    analysisResult,
    isAnalyzing,
    isGeneratingVivaReport,
    vivaReportError,
    vivaPdfUrl,
    vivaReportStatus,
    vivaPreviewHtml,

    // Actions
    triggerAnalysis,
    generateVivaReport,
    downloadVivaPdf,
    resetViva,

    // Report info fields (reuse from session store)
    studentName,
    assignmentName,
    courseName,
    onStudentNameChange: setStudentName,
    onAssignmentNameChange: setAssignmentName,
    onCourseNameChange: setCourseName,
  }
}

