/**
 * XSS sanitization for notebook output rendering (T-01-07 mitigation).
 *
 * Strips dangerous HTML content from notebook output cells before they
 * are rendered in the browser via dangerouslySetInnerHTML.
 */

const SCRIPT_TAG_REGEX = /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi
const ON_EVENT_REGEX = /\s+on\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi
const JAVASCRIPT_URL_REGEX = /href\s*=\s*(?:"javascript:[^"]*"|'javascript:[^']*')/gi
const IFRAME_TAG_REGEX = /<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi
const IFRAME_SELF_CLOSING_REGEX = /<iframe\b[^>]*\/?>/gi
const OBJECT_TAG_REGEX = /<object\b[^<]*(?:(?!<\/object>)<[^<]*)*<\/object>/gi
const EMBED_TAG_REGEX = /<embed\b[^>]*\/?>/gi

/**
 * Sanitize notebook output HTML text by removing dangerous content.
 * Returns plain text safe for string display, or removes dangerous
 * elements from HTML that will be rendered via innerHTML.
 */
export function sanitizeOutput(text: string): string {
  if (!text) return ''

  let sanitized = text

  // Remove <script> tags and their content
  sanitized = sanitized.replace(SCRIPT_TAG_REGEX, '')

  // Remove <iframe> tags and their content
  sanitized = sanitized.replace(IFRAME_TAG_REGEX, '')
  sanitized = sanitized.replace(IFRAME_SELF_CLOSING_REGEX, '')

  // Remove <object> tags
  sanitized = sanitized.replace(OBJECT_TAG_REGEX, '')

  // Remove <embed> tags
  sanitized = sanitized.replace(EMBED_TAG_REGEX, '')

  // Remove on* event handlers (onclick, onerror, onload, etc.)
  sanitized = sanitized.replace(ON_EVENT_REGEX, '')

  // Remove javascript: URLs in href attributes
  sanitized = sanitized.replace(JAVASCRIPT_URL_REGEX, '')

  // Strip remaining HTML tags for plain text rendering
  // (output cells rendered as text, not HTML)
  sanitized = sanitized.replace(/<[^>]*>/g, '')

  return sanitized
}

/**
 * Sanitize HTML that will be rendered via dangerouslySetInnerHTML.
 * This is more permissive than sanitizeOutput — it keeps structural HTML
 * but removes dangerous elements and attributes.
 */
export function sanitizeOutputHtml(text: string): string {
  if (!text) return ''

  let sanitized = text

  // Remove <script> tags
  sanitized = sanitized.replace(SCRIPT_TAG_REGEX, '')

  // Remove <iframe> tags
  sanitized = sanitized.replace(IFRAME_TAG_REGEX, '')
  sanitized = sanitized.replace(IFRAME_SELF_CLOSING_REGEX, '')

  // Remove <object> tags
  sanitized = sanitized.replace(OBJECT_TAG_REGEX, '')

  // Remove <embed> tags
  sanitized = sanitized.replace(EMBED_TAG_REGEX, '')

  // Remove on* event handlers
  sanitized = sanitized.replace(ON_EVENT_REGEX, '')

  // Remove javascript: URLs
  sanitized = sanitized.replace(JAVASCRIPT_URL_REGEX, '')

  return sanitized
}

import { createContext, useContext, useEffect, useState, ReactNode } from 'react'

type Theme = 'light' | 'dark'

interface ThemeContextValue {
  theme: Theme
  toggleTheme: () => void
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)

function getInitialTheme(): Theme {
  if (typeof window !== 'undefined') {
    const stored = localStorage.getItem('theme')
    if (stored === 'light' || stored === 'dark') return stored
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark'
  }
  return 'light'
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>(getInitialTheme)

  useEffect(() => {
    const root = document.documentElement
    if (theme === 'dark') {
      root.classList.add('dark')
    } else {
      root.classList.remove('dark')
    }
    localStorage.setItem('theme', theme)
  }, [theme])

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light')

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext)
  if (!ctx) throw new Error('useTheme must be used within a ThemeProvider')
  return ctx
}

