import { useCallback, useState, useEffect } from 'react'
import { FileText, BarChart3, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import StepWizard from '@/components/StepWizard'
import type { Step } from '@/components/StepWizard'
import UploadZone from '@/components/UploadZone'
import BatchFileList from '@/components/BatchFileList'
import BatchProgressBar from '@/components/BatchProgressBar'
import EvaluationProgress from '@/components/EvaluationProgress'
import BatchComparisonTable from '@/components/BatchComparisonTable'
import BatchSideDrawer from '@/components/BatchSideDrawer'
import FloatingActionBar from '@/components/FloatingActionBar'
import CohortSummaryWidget from '@/components/CohortSummaryWidget'
import RubricSelector from '@/components/RubricSelector'
import ErrorDisplay from '@/components/ErrorDisplay'
import { useBatch } from '@/hooks/useBatch'
import { useComparisonData } from '@/hooks/useComparisonData'
import { useCohort } from '@/hooks/useCohort'
import { useBatchStore } from '@/stores/batchStore'
import { useSessionStore } from '@/stores/sessionStore'
import type { ComparisonRow, RubricTemplate, ReportMode } from '@/types/api'

interface BatchDashboardProps {
  onBackToUpload: () => void
}

export default function BatchDashboard({ onBackToUpload }: BatchDashboardProps) {
  const {
    queueFiles,
    evaluationStatus,
    isEvaluating,
    isUploading,
    uploadError,
    startEvaluation,
    removeFile,
    batchSessionId,
    uploadBatchFiles,
  } = useBatch()

  const selectedRubric = useBatchStore((s) => s.selectedRubric)
  const setSelectedRubric = useBatchStore((s) => s.setSelectedRubric)
  const isReevaluating = useBatchStore((s) => s.isReevaluating)

  const [currentStep, setCurrentStep] = useState(0)
  const [evaluationMode, setEvaluationMode] = useState<ReportMode>('scorecard')
  const [comparisonFetched, setComparisonFetched] = useState(false)

  const {
    comparisonData,
    isLoadingComparison,
    selectedStudent,
    selectStudent,
    fetchComparison,
    reevaluateNotebook,
    recalculateNotebook,
    updateRowScore,
  } = useComparisonData()

  const {
    cohortData: cohortSummaryData,
    isLoading: isCohortLoading,
    error: cohortError,
    refresh: refreshCohort,
  } = useCohort()

  // Sync batch session to session store so RubricSelector can save rubric
  const setSessionId = useSessionStore((s) => s.setSessionId)
  useEffect(() => {
    if (batchSessionId) {
      setSessionId(batchSessionId)
    }
  }, [batchSessionId, setSessionId])

  // Step advancement gating
  const allValidated = queueFiles.length > 0 && queueFiles.every(f => f.status === 'validated' || f.status === 'failed')
  const hasTerminalStatus = evaluationStatus
    ? ['completed', 'failed', 'completed_with_errors'].includes(evaluationStatus.overall_status)
    : false

  const batchProgress = evaluationStatus
    ? {
        step: `Evaluating ${evaluationStatus.completed + evaluationStatus.failed}/${evaluationStatus.total} notebooks`,
        status: evaluationStatus.overall_status === 'processing' ? 'in_progress' : evaluationStatus.overall_status,
      }
    : null

  // Fetch comparison data once when reaching comparison step
  useEffect(() => {
    if (currentStep === 3 && comparisonData === null && !comparisonFetched) {
      setComparisonFetched(true)
      fetchComparison()
    }
  }, [currentStep, comparisonData, fetchComparison, comparisonFetched])

  const handleRubricReady = useCallback((rubric: RubricTemplate) => {
    setSelectedRubric(rubric)
  }, [setSelectedRubric])

  const handleStartEvaluation = useCallback(() => {
    startEvaluation()
    setCurrentStep(2)
  }, [startEvaluation])

  const handleSelectStudent = useCallback((filename: string | null) => {
    selectStudent(filename)
  }, [selectStudent])

  const handleReevaluate = useCallback((filename: string) => {
    reevaluateNotebook(filename)
  }, [reevaluateNotebook])

  const handleRecalculate = useCallback((filename: string) => {
    recalculateNotebook(filename)
  }, [recalculateNotebook])

  const handleScoreEdit = useCallback((filename: string, criterionName: string, newScore: number) => {
    updateRowScore(filename, criterionName, newScore)
  }, [updateRowScore])

  const handleReevaluateAll = useCallback(async () => {
    if (!comparisonData) return
    const BATCH_SIZE = 3
    const filenames = comparisonData.rows
      .filter((r) => r.status === 'completed' || r.status === 'failed')
      .map((r) => r.filename)

    for (let i = 0; i < filenames.length; i += BATCH_SIZE) {
      const batch = filenames.slice(i, i + BATCH_SIZE)
      await Promise.all(batch.map((fn) => reevaluateNotebook(fn)))
    }
  }, [comparisonData, reevaluateNotebook])

  const selectedRow: ComparisonRow | null = comparisonData
    ? comparisonData.rows.find((r) => r.filename === selectedStudent) || null
    : null

  const isReevaluatingAll = Object.values(isReevaluating).some(Boolean) &&
    (comparisonData?.rows.filter(r => r.status === 'completed' || r.status === 'failed').length ?? 0) > 1

  // ---- StepWizard handlers ----
  const handleNext = useCallback(() => {
    if (currentStep === 1) {
      handleStartEvaluation()
    } else {
      setCurrentStep((s) => Math.min(s + 1, 3))
    }
  }, [currentStep, handleStartEvaluation])

  const handleBack = useCallback(() => {
    if (currentStep === 0) {
      onBackToUpload()
    } else {
      setCurrentStep((s) => s - 1)
    }
  }, [currentStep, onBackToUpload])

  const canGoNext = useCallback((): boolean => {
    switch (currentStep) {
      case 0: return allValidated
      case 1: return selectedRubric !== null
      case 2: return hasTerminalStatus
      case 3: return false
      default: return false
    }
  }, [currentStep, allValidated, selectedRubric, hasTerminalStatus])

  const canGoBack = true

  const nextLabel = currentStep === 0 ? 'Configure Rubric'
    : currentStep === 1 ? 'Evaluate All'
    : currentStep === 2 ? 'Review Results'
    : 'New Evaluation'

  const backLabel = currentStep === 0 ? 'Back to Home' : 'Back'

  // ---- Step definitions ----
  const steps: Step[] = [
    {
      id: 'upload',
      title: 'Upload',
      description: 'Upload .ipynb files',
      component: (
        <div className="space-y-6">
          <UploadZone
            onFilesSelected={uploadBatchFiles}
            onRemove={() => queueFiles.length > 0 && useBatchStore.getState().setQueueFiles([])}
            maxSizeMB={20}
            disabled={isUploading}
            multiple={true}
          />
          {queueFiles.length > 0 && (
            <BatchFileList files={queueFiles} onRemove={removeFile} disabled={isUploading} />
          )}
          {uploadError && <ErrorDisplay error={uploadError} variant="inline" onDismiss={() => {}} />}
        </div>
      ),
    },
    {
      id: 'rubric',
      title: 'Rubric',
      description: 'Configure evaluation rubric',
      component: (
        <div className="space-y-6">
          <RubricSelector
            onRubricReady={handleRubricReady}
            initialRubric={selectedRubric}
          />
          <div>
            <label className="block text-sm font-medium mb-3">Evaluation Mode</label>
            <div className="grid grid-cols-2 gap-3">
              <Card
                className={`cursor-pointer transition-all hover:border-primary/50 ${
                  evaluationMode === 'scorecard' ? 'ring-2 ring-primary border-primary bg-primary/5' : ''
                }`}
                onClick={() => setEvaluationMode('scorecard')}
              >
                <CardContent className="p-4 text-center">
                  <BarChart3 size={20} className="mx-auto text-primary mb-2" />
                  <h4 className="font-medium text-sm">Scorecard</h4>
                  <p className="text-xs text-muted-foreground mt-1">Compact scores & marks</p>
                </CardContent>
              </Card>
              <Card
                className={`cursor-pointer transition-all hover:border-primary/50 ${
                  evaluationMode === 'detailed' ? 'ring-2 ring-primary border-primary bg-primary/5' : ''
                }`}
                onClick={() => setEvaluationMode('detailed')}
              >
                <CardContent className="p-4 text-center">
                  <FileText size={20} className="mx-auto text-primary mb-2" />
                  <h4 className="font-medium text-sm">Detailed</h4>
                  <p className="text-xs text-muted-foreground mt-1">Full evaluation report</p>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      ),
    },
    {
      id: 'evaluate',
      title: 'Evaluate',
      description: 'Run AI evaluation',
      component: (
        <div className="space-y-6">
          <EvaluationProgress
            progress={batchProgress}
            isEvaluating={isEvaluating && !hasTerminalStatus}
            onStartEvaluation={handleStartEvaluation}
            evaluated={hasTerminalStatus}
          />
          {evaluationStatus && (
            <Card>
              <CardContent className="p-6">
                <h3 className="text-base font-semibold mb-4">Batch Progress</h3>
                <BatchProgressBar status={evaluationStatus} />
              </CardContent>
            </Card>
          )}
        </div>
      ),
    },
    {
      id: 'comparison',
      title: 'Review',
      description: 'Compare results',
      component: (
        <div className="space-y-6">
          <Card>
            <CardContent className="p-4 flex items-center justify-between flex-wrap gap-3">
              <div className="flex items-center gap-4">
                <span className="text-xs font-mono text-muted-foreground">
                  {batchSessionId?.slice(0, 8)}...
                </span>
                <span className="text-xs text-muted-foreground">
                  {comparisonData?.total || 0} students
                </span>
                {selectedRubric && (
                  <span className="text-xs text-muted-foreground">
                    Rubric: {selectedRubric.name}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2">
                <select
                  value={evaluationMode}
                  onChange={(e) => setEvaluationMode(e.target.value as ReportMode)}
                  className="text-xs px-2 py-1.5 rounded border border-input bg-background"
                >
                  <option value="scorecard">Scorecard</option>
                  <option value="detailed">Detailed</option>
                </select>
                <Button variant="outline" size="sm" onClick={handleReevaluateAll} disabled={isReevaluatingAll}>
                  <RefreshCw size={14} className="mr-1" /> Re-evaluate All
                </Button>
              </div>
            </CardContent>
          </Card>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
            <div className="lg:col-span-3">
              <BatchComparisonTable
                data={comparisonData}
                loading={isLoadingComparison}
                selectedStudent={selectedStudent}
                onSelectStudent={handleSelectStudent}
                onScoreEdit={handleScoreEdit}
                isReevaluating={isReevaluating}
              />
            </div>
            <div className="lg:col-span-1">
              <CohortSummaryWidget
                data={cohortSummaryData}
                isLoading={isCohortLoading}
                error={cohortError}
                onRefresh={refreshCohort}
              />
            </div>
          </div>

          <BatchSideDrawer
            row={selectedRow}
            open={selectedStudent !== null}
            onClose={() => handleSelectStudent(null)}
            onReevaluate={handleReevaluate}
            onRecalculate={handleRecalculate}
            isReevaluating={selectedStudent ? (isReevaluating[selectedStudent] || false) : false}
          />

          <FloatingActionBar
            comparisonData={comparisonData}
            onReevaluateAll={handleReevaluateAll}
            isReevaluatingAll={isReevaluatingAll}
          />
        </div>
      ),
    },
  ]

  return (
    <>
      <StepWizard
        steps={steps}
        currentStep={currentStep}
        onNext={handleNext}
        onBack={handleBack}
        canGoNext={canGoNext()}
        canGoBack={canGoBack}
        nextLabel={nextLabel}
        backLabel={backLabel}
        containerClassName={currentStep === 3 ? '!max-w-full' : undefined}
      />

      {uploadError && currentStep !== 0 && (
        <ErrorDisplay error={uploadError} variant="toast" onDismiss={() => {}} />
      )}
    </>
  )
}

import type {
  UploadResponse,
  UnderstandingResponse,
  SessionResponse,
  ApiError,
  RubricListResponse,
  RubricTemplate,
  EvaluationResult,
  EvaluationResponse,
  ReportRequest,
  ReportTriggerResponse,
  ReportStatusResponse,
  AnalysisTriggerResponse,
  VivaReportRequest,
  VivaReportTriggerResponse,
  VivaReportStatusResponse,
  BatchUploadResponse,
  BatchStatusResponse,
  BatchEvaluateResponse,
  ComparisonResponse,
  ReEvaluateResponse,
  CohortSummaryResponse,
} from '@/types/api'

const API_BASE = '/api'
const REQUEST_TIMEOUT_MS = 30000

class ApiClientError extends Error {
  public apiError: ApiError
  public status: number

  constructor(apiError: ApiError, status: number) {
    super(apiError.message)
    this.name = 'ApiClientError'
    this.apiError = apiError
    this.status = status
  }
}

async function fetchWithTimeout(
  url: string,
  options: RequestInit = {},
  timeoutMs: number = REQUEST_TIMEOUT_MS
): Promise<Response> {
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    })
    return response
  } finally {
    clearTimeout(timeoutId)
  }
}

async function parseErrorResponse(response: Response): Promise<ApiError> {
  try {
    return await response.json()
  } catch {
    return {
      error: 'network_error',
      message: `Request failed with status ${response.status}`,
      details: [],
    }
  }
}

export const apiClient = {
  async uploadFile(file: File, sessionId?: string): Promise<UploadResponse> {
    const formData = new FormData()
    formData.append('file', file)

    const headers: Record<string, string> = {}
    if (sessionId) headers['session-id'] = sessionId

    const response = await fetchWithTimeout(`${API_BASE}/upload`, {
      method: 'POST',
      body: formData,
      headers,
    })

    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }

    return response.json()
  },

  async getUnderstanding(sessionId: string): Promise<UnderstandingResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/understand/${sessionId}`,
      { method: 'POST' }
    )

    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }

    return response.json()
  },

  async getUnderstandingStream(
    sessionId: string,
    onChunk: (text: string) => void,
    onDone: () => void,
    onError: (error: ApiClientError) => void
  ): Promise<void> {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 60000)

    try {
      const response = await fetch(
        `${API_BASE}/understand/${sessionId}/stream`,
        {
          method: 'GET',
          signal: controller.signal,
        }
      )

      if (!response.ok) {
        const error = await parseErrorResponse(response)
        onError(new ApiClientError(error, response.status))
        return
      }

      const reader = response.body?.getReader()
      if (!reader) {
        onError(
          new ApiClientError(
            { error: 'stream_error', message: 'Response body is not readable', details: [] },
            0
          )
        )
        return
      }

      const decoder = new TextDecoder()
      let buffer = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        // Process SSE data lines
        const lines = buffer.split('\n')
        buffer = lines.pop() || '' // Keep incomplete line in buffer

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6)
            if (data === '[DONE]') {
              onDone()
              return
            }
            try {
              const parsed = JSON.parse(data)
              if (parsed.content) {
                onChunk(parsed.content)
              }
            } catch {
              // If not JSON, treat the raw data as text
              if (data) onChunk(data)
            }
          }
        }
      }

      onDone()
    } catch (err) {
      clearTimeout(timeoutId)
      if (err instanceof ApiClientError) {
        onError(err)
      } else {
        onError(
          new ApiClientError(
            {
              error: 'stream_error',
              message: err instanceof Error ? err.message : 'Stream connection failed',
              details: [],
            },
            0
          )
        )
      }
    }
  },

  async getSession(sessionId: string): Promise<SessionResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/session/${sessionId}`,
      {}
    )

    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }

    return response.json()
  },

  // --- Rubric API ---

  async getRubricTemplates(): Promise<RubricListResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/rubric/templates`)
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  async saveRubric(rubric: RubricTemplate, sessionId: string): Promise<{ status: string; session_id: string }> {
    const response = await fetchWithTimeout(`${API_BASE}/rubric/save?session_id=${sessionId}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(rubric),
    })
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  // --- Evaluation API ---

  async evaluateNotebook(sessionId: string): Promise<EvaluationResult> {
    const response = await fetchWithTimeout(`${API_BASE}/evaluate/${sessionId}`, { method: 'POST' })
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    const data: EvaluationResponse = await response.json()
    return data.evaluation
  },

  async evaluateNotebookStream(
    sessionId: string,
    onStep: (step: string, status: string) => void,
    onCriterion: (criterion: string, score: number) => void,
    onResult: (result: EvaluationResult) => void,
    onError: (error: ApiClientError) => void,
  ): Promise<void> {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 120000)

    try {
      const response = await fetch(
        `${API_BASE}/evaluate/${sessionId}/stream`,
        { method: 'GET', signal: controller.signal }
      )

      if (!response.ok) {
        const error = await parseErrorResponse(response)
        onError(new ApiClientError(error, response.status))
        return
      }

      const reader = response.body?.getReader()
      if (!reader) {
        onError(
          new ApiClientError(
            { error: 'stream_error', message: 'Response body is not readable', details: [] },
            0
          )
        )
        return
      }

      const decoder = new TextDecoder()
      let buffer = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6)
            if (data === '[DONE]') {
              return
            }
            try {
              const parsed = JSON.parse(data)
              const eventType = parsed.type || ''

              if (eventType === 'step') {
                onStep(parsed.data?.step || '', parsed.data?.status || '')
              } else if (eventType === 'criterion') {
                onCriterion(parsed.data?.criterion || '', parsed.data?.score ?? 0)
              } else if (eventType === 'result') {
                onResult(parsed.data as EvaluationResult)
              } else if (eventType === 'error') {
                onError(
                  new ApiClientError(
                    { error: 'evaluation_error', message: parsed.data?.message || 'Evaluation error', details: [] },
                    0
                  )
                )
                return
              } else if (eventType === 'done') {
                return
              }
            } catch {
              // Skip unparseable lines
            }
          }
        }
      }
    } catch (err) {
      clearTimeout(timeoutId)
      if (err instanceof ApiClientError) {
        onError(err)
      } else {
        onError(
          new ApiClientError(
            {
              error: 'stream_error',
              message: err instanceof Error ? err.message : 'Stream connection failed',
              details: [],
            },
            0
          )
        )
      }
    }
  },

  // --- Report API ---

  async generateReport(sessionId: string, request: ReportRequest): Promise<ReportTriggerResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/report/${sessionId}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
    })
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  async getReportStatus(sessionId: string): Promise<ReportStatusResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/report/${sessionId}/status`)
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  downloadReportUrl(sessionId: string): string {
    return `${API_BASE}/report/${sessionId}/download`
  },

  // --- Analysis & Viva Report API (Phase 3) ---

  async triggerAnalysis(sessionId: string): Promise<AnalysisTriggerResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/analyze/${sessionId}`, {
      method: 'POST',
    })
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  async triggerVivaReport(sessionId: string, request: VivaReportRequest): Promise<VivaReportTriggerResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/viva-report/${sessionId}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
    })
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  async getVivaReportStatus(sessionId: string): Promise<VivaReportStatusResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/viva-report/${sessionId}/status`)
    if (!response.ok) throw new ApiClientError(await parseErrorResponse(response), response.status)
    return response.json()
  },

  downloadVivaReportUrl(sessionId: string): string {
    return `${API_BASE}/viva-report/${sessionId}/download`
  },

  // --- Batch API (Phase 5) ---

  async uploadBatch(files: File[], sessionId?: string): Promise<BatchUploadResponse> {
    const formData = new FormData()
    for (const file of files) {
      formData.append('files', file)
    }

    const headers: Record<string, string> = {}
    if (sessionId) headers['session-id'] = sessionId

    const response = await fetchWithTimeout(`${API_BASE}/upload/batch`, {
      method: 'POST',
      body: formData,
      headers,
    })
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  async getBatchStatus(sessionId: string): Promise<BatchStatusResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/batch/${sessionId}/status`)
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  async triggerBatchEvaluation(sessionId: string): Promise<BatchEvaluateResponse> {
    const response = await fetchWithTimeout(`${API_BASE}/batch/${sessionId}/evaluate`, {
      method: 'POST',
    })
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  // --- Batch Dashboard & Export (Phase 6) ---

  async getComparison(sessionId: string): Promise<ComparisonResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/batch/${sessionId}/comparison`
    )
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  async reevaluateNotebook(sessionId: string, filename: string): Promise<ReEvaluateResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/batch/${sessionId}/notebooks/${encodeURIComponent(filename)}/re-evaluate`,
      { method: 'POST' }
    )
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  async recalculateNotebook(sessionId: string, filename: string): Promise<ReEvaluateResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/batch/${sessionId}/notebooks/${encodeURIComponent(filename)}/recalculate`,
      { method: 'POST' }
    )
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  async getCohortSummary(sessionId: string): Promise<CohortSummaryResponse> {
    const response = await fetchWithTimeout(
      `${API_BASE}/batch/${sessionId}/cohort/summary`
    )
    if (!response.ok) {
      const error = await parseErrorResponse(response)
      throw new ApiClientError(error, response.status)
    }
    return response.json()
  },

  // --- Export Download Helpers (Phase 6) ---

  getExportZipUrl(sessionId: string, mode: 'scorecard' | 'detailed' | 'both' = 'scorecard'): string {
    return `${API_BASE}/batch/${sessionId}/export/zip?mode=${mode}`
  },

  getExportCsvUrl(sessionId: string): string {
    return `${API_BASE}/batch/${sessionId}/export/csv`
  },

  downloadExport(url: string, filename: string): void {
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = filename
    document.body.appendChild(anchor)
    anchor.click()
    document.body.removeChild(anchor)
  },
}

