import { create } from 'zustand'
import type {
  QueueFileEntry,
  BatchStatusResponse,
  ComparisonResponse,
  RubricTemplate,
} from '@/types/api'

interface BatchState {
  // Upload queue (Phase 5)
  queueFiles: QueueFileEntry[]
  batchSessionId: string | null
  isUploading: boolean

  // Evaluation (Phase 5)
  isEvaluating: boolean
  evaluationStatus: BatchStatusResponse | null

  // Rubric configuration (shared across batch)
  selectedRubric: RubricTemplate | null

  // Comparison & dashboard (Phase 6)
  comparisonData: ComparisonResponse | null
  isLoadingComparison: boolean
  selectedStudent: string | null  // filename of selected notebook
  isReevaluating: Record<string, boolean>  // filename -> loading state

  // Actions — Phase 5 (upload + evaluation)
  setQueueFiles: (files: QueueFileEntry[]) => void
  addToQueue: (entries: QueueFileEntry[]) => void
  updateFileStatus: (id: string, updates: Partial<QueueFileEntry>) => void
  removeFromQueue: (id: string) => void
  clearQueue: () => void
  setBatchSessionId: (id: string | null) => void
  setIsUploading: (uploading: boolean) => void
  setIsEvaluating: (evaluating: boolean) => void
  setEvaluationStatus: (status: BatchStatusResponse | null) => void

  // Actions — Rubric
  setSelectedRubric: (rubric: RubricTemplate | null) => void

  // Actions — Phase 6 (comparison + dashboard)
  setComparisonData: (data: ComparisonResponse | null) => void
  setIsLoadingComparison: (loading: boolean) => void
  setSelectedStudent: (filename: string | null) => void
  setReevaluating: (filename: string, isReevaluating: boolean) => void
  updateComparisonRow: (filename: string, updates: Partial<ComparisonResponse['rows'][0]>) => void

  reset: () => void
  resetUploadFlow: () => void
}

const initialState = {
  queueFiles: [],
  batchSessionId: null,
  isUploading: false,
  isEvaluating: false,
  evaluationStatus: null,
  selectedRubric: null,
  comparisonData: null,
  isLoadingComparison: false,
  selectedStudent: null,
  isReevaluating: {},
}

export const useBatchStore = create<BatchState>((set) => ({
  ...initialState,

  // Phase 5 — Upload queue actions
  setQueueFiles: (files: QueueFileEntry[]) => set({ queueFiles: files }),
  addToQueue: (entries: QueueFileEntry[]) =>
    set((state) => ({ queueFiles: [...state.queueFiles, ...entries] })),
  updateFileStatus: (id: string, updates: Partial<QueueFileEntry>) =>
    set((state) => ({
      queueFiles: state.queueFiles.map((f) =>
        f.id === id ? { ...f, ...updates } : f
      ),
    })),
  removeFromQueue: (id: string) =>
    set((state) => ({
      queueFiles: state.queueFiles.filter((f) => f.id !== id),
    })),
  clearQueue: () => set({ queueFiles: [] }),

  // Phase 5 — Evaluation actions
  setBatchSessionId: (id: string | null) => set({ batchSessionId: id }),
  setIsUploading: (uploading: boolean) => set({ isUploading: uploading }),
  setIsEvaluating: (evaluating: boolean) => set({ isEvaluating: evaluating }),
  setEvaluationStatus: (status: BatchStatusResponse | null) =>
    set({ evaluationStatus: status }),

  // Rubric actions
  setSelectedRubric: (rubric: RubricTemplate | null) => set({ selectedRubric: rubric }),

  // Phase 6 — Comparison & Dashboard actions
  setComparisonData: (data: ComparisonResponse | null) =>
    set({ comparisonData: data }),
  setIsLoadingComparison: (loading: boolean) =>
    set({ isLoadingComparison: loading }),
  setSelectedStudent: (filename: string | null) =>
    set({ selectedStudent: filename }),
  setReevaluating: (filename: string, isReevaluating: boolean) =>
    set((state) => ({
      isReevaluating: { ...state.isReevaluating, [filename]: isReevaluating },
    })),
  updateComparisonRow: (filename: string, updates: Partial<ComparisonResponse['rows'][0]>) =>
    set((state) => {
      if (!state.comparisonData) return state
      return {
        comparisonData: {
          ...state.comparisonData,
          rows: state.comparisonData.rows.map((row) =>
            row.filename === filename ? { ...row, ...updates } : row
          ),
        },
      }
    }),

  reset: () => set({ ...initialState, selectedRubric: null }),

  // Explicit reset for back-to-upload
  resetUploadFlow: () => set({
    queueFiles: [],
    isUploading: false,
    isEvaluating: false,
    evaluationStatus: null,
    selectedRubric: null,
    comparisonData: null,
    isLoadingComparison: false,
    selectedStudent: null,
    isReevaluating: {},
  }),
}))

